quests[48873] = { id = 48873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flauschig und warm", description = "Diese Hütte ist der größte Umschlagsplatz für Felle und Leder für Boralus.\n\n<Kenninger wirft sich in die Brust.>\n\nUnd als Betreiber ist es meine Pflicht, dafür zu sorgen, dass jede Bestellung rechtzeitig ausgeführt wird. Wegen der kürzlichen Verzögerungen habe ich mich hierher auf den Weg gemacht, um herauszufinden, ob die Holstens meine Unterstützung benötigen.\n\nWir können jede Hilfe brauchen, also nehmt dieses Messer und beschafft ein paar Pelze von den Bären am nahe gelegenen Pass.", sourceObjective = "Häutet 6 monströse Grizzlys.", completion = "Diese Felle sehen ordentlich aus. Eure Fähigkeiten könnten die Rückschläge durch die \"Unfälle\" wieder ausgleichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48874] = { id = 48874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn doch der Rost nicht wäre", description = "Die Fallen, die wir im Feld aufgestellt haben, müssen regelmäßig kontrolliert werden. Einige von ihnen sind ziemlich alt und lösen zur falschen Zeit aus. Wenn wir nur mehr Gelder für diese Art der Ausrüstung erhalten würden.\n\n<Die Meisterschützin blickt zu Lord Kenninger hinüber.>\n\nKönntet Ihr die ausgelösten Fallen wieder aufstellen, während Ihr dort draußen auf der Jagd seid?", sourceObjective = "Stellt 5 Bärenfallen neu auf.", completion = "Wie mir scheint, verfügt Ihr noch immer über all Eure Gliedmaßen. Und ich hatte schon gehofft, ich könnte Kenninger überzeugen, ein paar neue Fallen zu kaufen. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[48875] = { id = 48875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gut vermischt" }
quests[48879] = { id = 48879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd auf Falkeneier", description = "Bevor Alina uns auf unsere große Jagd schickt, müssen wir uns noch um etwas kümmern...\n\nIch bin am Verhungern! Und niemand kann auf leeren Magen jagen.\n\nEs gibt Falken in der Gegend, also gibt es auch Falkeneier. Ich weiß nicht, wie gut ein Omelett daraus wäre, doch ich bin immer für kulinarische Abenteuer bereit!\n\nWärt Ihr so gut und würdet mir ein paar beschaffen, bevor wir hier beginnen?", sourceObjective = "Sammelt 12 Falkeneier ein.", progress = "Habt Ihr schon genug Eier gefunden? Ihr wisst doch, was die kleinen Goblins sagen: Zeit ist Geld!", completion = "Fantastisch! Da kann man nur noch hoffen, dass Falkeneier auch schmecken...", sourceObjectiveStatus = "unverified-source-field" }
quests[48880] = { id = 48880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Miese Möwen", description = "Muss... fangen... Brauche mehr...\n\nDie Möwen... beißen... kratzen... schnappen...\n\nMuss sie loswerden... aber... Ich muss... fangen...", sourceObjective = "Tötet 10 territoriale Flussmöwen bei der Matschflosserhütte.", completion = "Die Möwen sind... nicht mehr...\n\nJetzt... kann ich mehr fangen...\n\nJa... mehr fangen...", sourceObjectiveStatus = "unverified-source-field" }
quests[48881] = { id = 48881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angebissen", description = "<Diese Angelruten wurden wohl von Art zurückgelassen. An einigen davon haben Fische angebissen.\n\nHolt sie ein und schaut nach, was Ihr gefangen habt.>", sourceObjective = "Holt 5 Angelruten am Schnappklauenstrand ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[48882] = { id = 48882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Messer rein, Gedärme raus", description = "<Anscheinend sind einige der Fische, die die Möwen Art gestohlen haben, noch unversehrt.\n\nÜber die Innereien dieser Fische wird er sich bestimmt sehr freuen.>", sourceObjective = "Sammelt 9 Matschflosserinnereien von intakten Matschflossern bei der Matschflosserhütte.", progress = "Was ist... das?", completion = "Ja... jaaaaaa...\n\nMehr Gedärme... mehr Innereien... nur das Beste...", sourceObjectiveStatus = "unverified-source-field" }
quests[48883] = { id = 48883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mach die Flatter!", description = "Noch einer mehr... klaut meine Köder... meinen Fisch...\n\nMeinen Finger...\n\nTötet ihn... und Ihr werdet belohnt werden...", sourceObjective = "Tötet Salzschnabel in der Matschflosserhütte.", completion = "Ist er tot?\n\nJa... jetzt kann ich wieder angeln... und ausnehmen... und fangen...\n\nNoch mehr Innereien... nur das Beste für die Schwestern...", sourceObjectiveStatus = "unverified-source-field" }
quests[48887] = { id = 48887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reinigung des Geistes", description = "Wenn Ihr Akunda in Euren Geist einlad'n wollt, dürft Ihr keine Angst un' kein Bedauern empfind'n. \n\nMeditiert am Schrein des Donners und stellt Euch den Dämonen, die im hintersten Winkel von Eurem Verstand lauern.", sourceObjective = "Meditiert am Schrein des Donners und stellt Euch Euren inneren Dämonen.", completion = "Man sieht Euch den Erfolg schon an. Ihr habt Frieden gefund'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[48888] = { id = 48888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Quell ist ewig", description = "Hier in den Dünen is' Wasser 'ne Seltenheit, doch im Tempel muss niemand verdurst'n.\n\nAkunda herrscht über den Sturm un' lässt nicht zu, dass die Quelle in der Nähe austrocknet.\n\nLeider lockt der Ewige Quell auch 'ne Menge Viecher an, die sich im Tempel breitmach'n. \n\nErlegt diese Tiere im Tal, bevor ihr zurückkehrt.", sourceObjective = "Tötet die Aasfresser von Rotfels in der Nähe des Ewigen Quells.", completion = "Die Quelle is' 'ne Gabe vom Loa un' wir müss'n sie um jeden Preis schütz'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[48889] = { id = 48889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilen der Vergangenheit", description = "Das erklärt, warum der Loa so still is'. Akunda hat selbst vergess'n, wer er is'!\n\nIrgendwer oder irgendetwas muss seine Macht missbrauch'n. \n\nOhne mit dem Loa zu sprech'n, werd'n wir nich' wissen, wie man ihm helf'n kann.\n\nIch kann 'n Ritual wirk'n, das Akundas Verstand vielleicht heilt. Aber das is' nicht ganz ohne Risiko.", sourceObjective = "Schützt Meijani, während sie Akundas Verstand heilt.", completion = "Ich brauch' Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[48890] = { id = 48890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pflichten eines Bluttrolls", description = "Ihr dürft nich' auffall'n, wenn keiner Verdacht schöpf'n soll. Das wird kein Zuckerschlecken.\n\nIm Lager verteilt werd'n Akkordarbeiter als Teil des Rituals gefesselt sein. Sie werd'n zum Test geschlag'n, um sie stärker zu mach'n.\n\nWenn es einer nich' schafft, wird er geopfert. Die, die es schaff'n, dürf'n die Zandalari bekämpf'n.\n\nWenn Ihr Euch einschleich'n wollt, müsst ihr diese Akkordarbeiter als Teil des Rituals \"test'n\". Das klingt komisch, aber so ist der Brauch.", sourceObjective = "Testet 5 unerprobte Akkordarbeiter.", completion = "Gute Arbeit. Niemand ahnt was. Konnt'n 'n paar dem Druck nich' standhalt'n?", sourceObjectiveStatus = "unverified-source-field" }
quests[48894] = { id = 48894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prüfung der Wahrheit", description = "Die im Tempel ham ihre früheren Leben hinter sich gelass'n. Sie ham sich voll un' ganz Akunda ergeb'n. \n\nDie letzte Prüfung is' vielleicht die wichtigste. \n\nDa wird die Wahrheit ans Licht komm'. \n\nIhr werdet Euren Namen aussprech'n, unter dem man Euch von dies'm Tag an kenn' wird.", sourceObjective = "Sprecht Euren Namen vor Akunda dem Erhabenen aus.", completion = "Ihr habt Euch als würdig erwies'n, unsren Tempel zu betret'n, Akunda.", sourceObjectiveStatus = "unverified-source-field" }
quests[48895] = { id = 48895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die perfekte Opfergabe", description = "Diese Opfergabe is' alles, was ich noch hab, aber ich find's nich' richtig, sie für mich selbst zu benutz'n, wenn ich weiß, dass Eure Freundin in Gefahr is'. \n\nSie hat mir das Leb'n gerettet, un' jetzt kann ich ihrs rett'n.\n\nNehmt die Opfergabe. Lasst mich nich' lange bitt'n.", sourceObjective = "Übergebt die Opfergabe Akunda dem Erhabenen beim Tempel von Akunda.", progress = "Bringt Ihr Geschenke für unsren Loa?", completion = "Das is' 'ne großzügige Opfergabe, aber 'n Geschenk allein reicht nich' aus, um unsren Tempel zu betret'n. \n\nErlösung kann man nich' erkaufen. Die muss man sich verdien'. \n\nAber Ihr habt Glück, es gibt viel Arbeit zu erledig'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[48896] = { id = 48896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen der Vergangenheit", description = "'ne alte Freundin von mir is' freiwillig in die Sande gegang'n, um das Wiss'n der Vergangenheit zu erforsch'n. \n\nWenn wer diese Waffe find'n kann, dann is' das Julwaba. \n\nIch hab zuletzt gehört, dass sie in den Ruinen um die große Pyramide grab'n wollte.", sourceObjective = "Reist mit Meerahs Wagen, um nach Julwaba zu suchen.", completion = "Es is' offensichtlich, dass Jakra'zet nicht aufhör'n wird, bis ich tot bin.", sourceObjectiveStatus = "unverified-source-field" }
quests[48897] = { id = 48897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgemacht ist abgemacht", description = "Jetzt, da Ihr 'nen Loaschutzpatron für Eure Zeit in Zuldazar erwählt habt, solltet Ihr dem König von Eurer Entscheidung erzähl'n.\n\nEr wird Wohlgefall'n daran find'n, dass Ihr Euch für den mächtig'n Gonk entschied'n habt.", sourceObjective = "Sprecht mit König Rastakhan.", completion = "Ihr habt Euch also für den Pfad von Gonk entschied'n. Möge der Loa Euch immer die Spuren Eurer Feinde zeig'n.\n\nIch persönlich folg dem Pfad von Rezan, dem Teufelssaurierloa der Könige. Wir hab'n allerdings seit Jahren nich' mehr gesproch'n.\n\nVielleicht sollte ich ihn wieder mal besuch'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[48898] = { id = 48898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glücksbringer", description = "Mein Vater würde das nicht zugeben, aber er ist wirklich abergläubisch. Ich glaube, ohne einen Glücksbringer wird er sich nie auf ein Pferd trauen!\n\nIch habe von einem Fuchs gehört, der sich herumtreibt und reichlich Hühner verspeist. Niemand kann ihn schnappen. Der ist vom Glück verfolgt! Vielleicht würde mein Vater Mut schöpfen, wenn er den Fuchsschwanz als Glücksbringer hätte!", sourceObjective = "Besorgt Glückschweifs Schwanz von Glückschweif an den Steinschnellklippen.", progress = "Fuchsschwänze bringen Glück, {name}. Ich glaube, dieser wird meinem Vater viel Mut machen!", completion = "Ich glaube, auch ich kann das Glück fühlen!", sourceObjectiveStatus = "unverified-source-field" }
quests[48899] = { id = 48899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherheit geht vor", description = "Die Verbindung zwischen Pferd und Reiter fasziniert mich und ich werde sie nie wirklich verstehen, bis ich sie selbst erfahre.\n\nAber dazu brauche ich... Rüstung! Ich meine, wie könnte man es wagen, sich ohne den passenden Schutz auf eine dieser Schönheiten zu schwingen?\n\nIn der Nähe habe ich einige Wasserfälle gesehen. An den Ufern der Gewässer muss es Muscheln geben! Würdet Ihr einem alten Tortollaner helfen, indem Ihr ein paar zu seinem Schutze sammelt?", sourceObjective = "Sammelt 8 unverwüstliche Muscheln an den Steinschnellklippen.", progress = "Schutz, ja. Ohne den passenden Schutz kann man sich nicht in gefährliche Lagen begeben!", completion = "Oh ja, diese Muschelschalen werden mir viel Schutz bieten!", sourceObjectiveStatus = "unverified-source-field" }
quests[48902] = { id = 48902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monströse Energie", description = "Habt Ihr schon mal von Aalsaft gehört? Ich weiß ja nicht, ob <ein/eine:r> {race} so etwas gefahrlos genießen kann, doch Tortollaner lieben ihn! Selbst der älteste Tortollaner wird von dem Energieschub wieder beschwingt.\n\nIch habe auf unserer Reise nördlich vom Anwesen Aale gesehen. Würdet Ihr ein wenig ihres Giftes für meinen Vater sammeln?", sourceObjective = "Sammelt 6 pulsierende Extrakte von Giftschuppenschlänglern an den Steinschnellklippen.", progress = "Mein Vater wird sich ja so freuen, wenn er sein Lieblingsgetränk sieht!", completion = "Oh Mann! Er wird sich so freuen!", sourceObjectiveStatus = "unverified-source-field" }
quests[48903] = { id = 48903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das perfekte Pferd ist es wert", description = "Nachdem Ihr all diese Sachen für mich gesammelt habt... ist es wohl an der Zeit, aufzusteigen, was?\n\nHui! So nervös war ich schon seit dreihundert Jahren nicht mehr! Würdet Ihr mir dabei helfen, den passenden Pferdepartner zu finden? Ich kann so eine schwere Entscheidung einfach nicht allein treffen!", sourceObjective = "Unterstützt Majo bei der Auswahl eines Pferdes und helft ihm beim Aufsteigen.", progress = "Mein Vater glaubt, dass alle Pferde ihre ganz eigene Persönlichkeit haben, genau wie Ihr oder ich. Für seinen ersten Ritt müssen wir das perfekte Pferd finden!", completion = "Er sitzt drauf! Er sitzt drauf!\n\nKeine Sorge, {name}. Ich bin sicher, es geht alles gut! Vielen Dank für Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[48904] = { id = 48904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friss den Köder", description = "Die Köder... sind fast aufgebraucht... ich muss fangen.\n\nDie Krabben... findet sie... fangt noch mehr...", sourceObjective = "Sammelt 15 Stücke Schnappklauenfleisch von Schnappklauenkrabben am Schnappklauenstrand.", progress = "Fast alle...", completion = "Ja... mehr Fleisch!\n\nIch darf nicht... kann nicht... aufhören!", sourceObjectiveStatus = "unverified-source-field" }
quests[48905] = { id = 48905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungewollte Schriftrollen", description = "Da Ihr sowieso schon hier in Natha'vor seid, könnt Ihr der restlichen Pilgerschaft vielleicht bei einem Problem helfen.\n\nDiese Trolle haben einige unserer Schriftrollen gestohlen. Warum sie das tun sollten, weiß keiner. Ich bezweifle, dass sie überhaupt lesen können.\n\nBitte bringt sie uns zurück. Im meinem Alter weiß ich diese ganzen Zauber nicht mehr auswendig! \n\nErst recht nicht die Heilzauber... und die wird Shoak brauchen, wenn Ihr diesen Tölpel gefunden habt.", sourceObjective = "Bergt 8 tortollanische Schriftrollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48909] = { id = 48909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noble Pflichten", description = "Von dem Zustand dieses Leichnams zu urteilen, würde ich vermuten, dass ein Tier mit mächtigen Klauen oder Zähnen dieses Lager heimgesucht hat. Ihr sagt, die Spur würde nach Westen führen? Hier hausen meist mehr als nur einer von Alinas Jägern. Ich frage mich, ob die anderen auch hinter dem Tier her sind.\n\nBeeilt Euch! Ich will nicht den ganzen Tag mit Warten verschwenden. Verfolgt unser bedrohliches Wild.", sourceObjective = "Spürt das mordende Monster auf und tötet es.", completion = "Danke, dass Ihr Euch um die Bedrohung gekümmert habt. Ich sorge dafür, dass die Verstorbenen einen gebührenden Abschied erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[48910] = { id = 48910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte für Krokuun", description = "Dieser unwirtliche Ort hat meinen Leuten nicht viel zu bieten. Wir verbringen fast die gesamte Zeit damit, Dinge zum Überleben zusammenzukratzen. Wenn ich mehr Vorräte hätte, könnte ich Euch einen weiteren Gratpirscher anbieten.\n\nWas meint Ihr, <Außerweltler/Außerweltlerin>?", sourceObjective = "Sammelt 150 Ordensressourcen.", progress = "Dieser unwirtliche Ort hat meinem Volk nicht viel zu bieten. Wir verbringen fast die gesamte Zeit damit, Dinge zum Überleben zusammenzukratzen. Wenn ich mehr Vorräte hätte, könnte ich Euch einen Gratpirscher anbieten.\n\nMit derart knappen Ressourcen kann ich jede Woche nur einen Krokulgratpirscher entbehren. Ich werde Euch denselben Handel nächste Woche noch einmal anbieten.", completion = "Was meint Ihr, Außerweltler?", sourceObjectiveStatus = "unverified-source-field" }
quests[48911] = { id = 48911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leerenimpfung", description = "Alle, die vom Schatten berührt worden sind, hinterlassen bei ihrem Ableben Spuren der Leere. Wenn Ihr bei Euren Reisen in die Stadt genug davon einsammeln könnt und dann zu mir zurückkehrt, werde ich ein besonders reines Destillat daraus herstellen. \n\nWir können noch mehr von meinen Leuten retten.", sourceObjective = "Sammelt 100 Fragmente kondensierter Leere.", progress = "Wenn Ihr die nötigen Zutaten bringt, kann ich mit der Destillation beginnen, {name}.\n\nMit derart knappen Ressourcen kann ich nur einmal pro Woche einen Leerenberührten befreien.", completion = "Noch eine Seele vor der Grausamkeit der Leere bewahrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[48912] = { id = 48912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versorgung des antorischen Feldzugs", description = "Zur Versorgung ihrer Kreuzzüge benötigt die Legion Rohmaterial von den eroberten Welten. Durchdringt die Legionsportale, vernichtet jeden Dämon, den Ihr findet, und haltet sie davon ab, ihre Kriegsmaschine mit Materialien zu versorgen.", sourceObjective = "Schließt 10 Invasionspunkte ab.", progress = "Durch den Feldzug gegen die Legion sind unsere Vorräte bedrohlich zur Neige gegangen. Bringt mir neue Vorräte, dann überlasse ich Euch einen Lichtgeschmiedeten.\n\nMit derart knappen Ressourcen kann ich jede Woche nur einen Lichtgeschmiedeten erübrigen.", completion = "Ein lichtgeschmiedeter Soldat kann sich durch ein Meer von Dämonen schlagen. Er wird Euch gute Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[48913] = { id = 48913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monelitvorkommen - Rang 1 freischalten", description = "Fasziniert, dass etwas so Reines weiterhin auf diesem Planeten gedeihen kann, pflückt Ihr die Pflanze. Ihr verspürt eine schwache Macht, die kurz von ihr ausgeht und dann verschwindet.\n\nAls sie in Euren Händen zerfällt, fragt Ihr Euch, ob es an diesem vom Licht verlassenen Ort wohl jemanden gibt, der weiß, wie man mit diesem wertvollen Kraut umgeht.Ihr erlernt:", sourceObjective = "Findet auf Argus jemanden, der Euch beibringen kann, wie Ihr Astralwinden ernten könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[48914] = { id = 48914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Monelitvorkommen - Rang 2 freischalten", description = "Fasziniert, dass etwas so Reines weiterhin auf diesem Planeten gedeihen kann, pflückt Ihr die Pflanze. Ihr verspürt eine schwache Macht, die kurz von ihr ausgeht und dann verschwindet.\n\nAls sie in Euren Händen zerfällt, fragt Ihr Euch, ob es an diesem vom Licht verlassenen Ort wohl jemanden gibt, der weiß, wie man mit diesem wertvollen Kraut umgeht.Ihr erlernt:", sourceObjective = "Findet auf Argus jemanden, der Euch beibringen kann, wie Ihr Astralwinden ernten könnt.", sourceObjectiveStatus = "unverified-source-field" }
