quests[48929] = { id = 48929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einschätzung des Gegners", description = "Die Nachricht, dass unsere Vorräte nicht für den Angriff auf Antorus ausreichen, wird Euren Hochexarchen sicher mit Sorge erfüllen. Er ist nicht gewohnt, seine viel gepriesene Armee des Lichts als unzureichend zu betrachten.\n\nDoch sein Stolz interessiert mich nicht. Während er eine neue Strategie sucht, werde ich den Boden mit Dämonenblut tränken.\n\nGeht nun. Vor unserem endgültigen Sieg muss noch vieles getan werden.", sourceObjective = "Sprecht mit Turalyon.", completion = "<Turalyon hört mit finsterer Miene zu.>", sourceObjectiveStatus = "unverified-source-field" }
quests[48931] = { id = 48931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erwachte Behemoths" }
