quests[48937] = { id = 48937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erschafft einen Portalgenerator des Netherwandlers." }
quests[48939] = { id = 48939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeigt, was in Euch steckt", description = "Scheint, als würdet Ihr die Grundlagen begreifen. Jetzt ist es an der Zeit, alles zu verbinden.\n\nBegebt Euch zum Ring. Sobald Ihr den Startschuss vernehmt, bleibt Euch eine Minute, um möglichst viele Punkte zu sammeln.\n\nGnolle sind einen Punkt wert. Durchbohrt sie mit der Harpune!\n\nFalls Ihr einen Papierzeppelin seht und mit Euren Bolas einwickelt, erhaltet Ihr dafür fünfzig Punkte!\n\nSprünge über Zäune zählen als Stil. Bei gutem Stil erhaltet Ihr mehr Punkte, während Ihr Euch um Gnolle und Zeppeline kümmert. Das ist wahnsinnig wichtig, also vergesst nicht, über die Zäune zu springen!", sourceObjective = "Steigt auf Böttcher auf, um mit Eurer Show zu beginnen, und erzielt mindestens 150 Punkte.", progress = "Die Reiterei von Kul Tiras ist ein wahres Musterbeispiel an Meisterhaftigkeit und Sportlichkeit!", completion = "Was für eine Darbietung!", sourceObjectiveStatus = "unverified-source-field" }
quests[48940] = { id = 48940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das westliche Trebuchet wurde verteidigt" }
quests[48941] = { id = 48941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kleiner Umweg", description = "Falls dieser Zirkel seine Energie wirklich aus diesen uralten Ruinen bezieht, weiß ich vielleicht, wie wir zurückschlagen können.\n\nTrefft mich an der ersten Weggabelung am Hochwegpass. Dort werde ich Euch etwas zeigen.", sourceObjective = "Trefft Luzilla Kronsteig am Hochwegpass in Drustvar.", completion = "Gut, dass Ihr hier seid.\n\nEs sieht leider so aus, als ob unsere Reise nicht sehr einfach werden wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[48942] = { id = 48942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yetirandale", description = "In letzter Zeit haben die Wachen ihre Patrouillen am Hochwegpass wohl vernachlässigt. Die Yetis haben sich hier breitgemacht und stehen uns jetzt im Weg.\n\nIch bin keine Soldatin, {class}, also kümmert Ihr Euch bitte um sie und ich versuche, um sie herumzuschleichen. Wenn wir sie von hier verjagen können, wird der Pass wieder für alle Reisenden sicher sein.", sourceObjective = "Tötet 8 Eispelzyetis auf der Gebirgshöhe.", completion = "Vielen Dank, {class}. Solange dieser Pass frei ist, kommen die Lieferungen sicher in Aroms Wehr an.\n\nSie werden in den kommenden Schlachten dringend gebraucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[48943] = { id = 48943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergungsrechte", description = "Dieser arme Händler wurde von den Yetis angegriffen. Wir können nichts mehr für ihn tun, aber es wäre nun wirklich eine Schande, seine Waren diesen Scheusalen zu überlassen.\n\nSchaut Euch um, ob Ihr noch brauchbare Vorräte findet. Bella kann sie für Euch tragen.\n\nKeine Sorge. Sie ist eine tapfere Stute, die nichts aus der Ruhe bringt.", sourceObjective = "Besorgt die eingewickelten Vorräte, das Fass mit gesalzenem Fisch, die gehärtete Schließkassette und den Eimer mit Getreide von der Gebirgshöhe.", completion = "Erstaunlich. Ich dachte nicht, dass noch so viel von der Lieferung übrig sein würde. Unsere Männer am Tor werden sich freuen.\n\nBella kennt den Weg, also wird sie das sicher zu den Männern bringen können. Dieser Ort ist sowieso zu gefährlich für sie.", sourceObjectiveStatus = "unverified-source-field" }
quests[48944] = { id = 48944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschichtsstunde", description = "Ihr fragt Euch sicher, warum ich Euch hierhergeführt habe.\n\nDiese Hütte birgt einen Geheimgang. Können wir ihn finden, so liegen dahinter die Antworten auf all Eure Fragen und vielleicht der Schlüssel zum Sieg gegen den Zirkel.\n\nHelft mir suchen, {class}.", sourceObjective = "Findet den Geheimgang in der Vergessenen Jagdhütte.", progress = "Irgendwo hier muss die Öffnung sein...", completion = "Ihr habt ihn gefunden! Ich wusste, dass das nicht nur Legenden waren.\n\nLos, gehen wir hinein.", sourceObjectiveStatus = "unverified-source-field" }
quests[48945] = { id = 48945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruinen von Gol Var", description = "Dahinter liegen noch mehr Ruinen, genau wie die, die auch der Zirkel suchte.\n\nAllerdings dienten diese Ruinen einem anderen Zweck. Damit wurde vor Tausenden von Jahren der Grundstein des Hauses Kronsteig gelegt.\n\nLasst uns hineingehen, dann erzähle ich Euch die ganze Geschichte.", sourceObjective = "Eskortiert Luzilla Kronsteig nach Gol Var.", progress = "Nur noch ein Stückchen...", completion = "Wer hätte gedacht, dass die Geschichte einiger der größten Krieger des Hauses Kronsteig in dieser muffigen Kammer ihren Anfang nahm?\n\nSeid Ihr bereit, in ihre Fußstapfen zu treten?", sourceObjectiveStatus = "unverified-source-field" }
quests[48946] = { id = 48946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Glutorden", description = "Diejenigen, die diese Waffen einst gegen die Drust erhoben, waren unter dem Namen Glutorden vereint. Sie nutzten die neu entdeckten Methoden und Instrumente der Gelehrten und konterten die Magie der Drust. So gewannen wir den Krieg.\n\nWenn der Zirkel die Magie der Drust gegen uns einsetzen will, dann nutzen wir die Waffen des Ordens.\n\nDas Wissen des Ordens ruht hier. Ohne eine starke Hand, es zu führen, ist es jedoch nutzlos.\n\nWollt Ihr diese starke Hand sein und die Waffen aufnehmen, {class}? Werdet Ihr den Glutorden wiederauferstehen lassen?", sourceObjective = "Nehmt den Folianten von Asche und Silber in Gol Var an Euch.", progress = "Was sagt Ihr?", completion = "Ihr erweist meiner Familie große Ehre, {class}. Die ehrbarsten Kronsteigs waren einst Inquisitoren des Ordens.\n\nWenn jemand würdig ist, dieses Erbe anzutreten, dann seid gewiss Ihr es.", sourceObjectiveStatus = "unverified-source-field" }
quests[48947] = { id = 48947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gol Koval", description = "Vor einiger Zeit ist eine Gruppe Jäger in die Hügel hinauf und seitdem verschwunden.\n\nMeine Nichte ist auch da oben und normalerweise ist sie nie so lange weg, ohne uns zu benachrichtigen. Könnt Ihr sie bitte suchen?\n\nSie wollte Richtung Gol Koval.", sourceObjective = "Findet Rebecca Kernig in Gol Koval.", completion = "Meine Tante hat Euch geschickt? Oh, das Licht segne diese Frau!", sourceObjectiveStatus = "unverified-source-field" }
quests[48948] = { id = 48948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nordpasshöhlen", description = "Ihr müsst mir helfen, bitte!\n\nMein Enkel hat sich bei den Höhlen im Norden verirrt. Ich habe solche Angst, dass die Troggs ihn vielleicht erwischt haben!\n\nMein Mann hat sich zwar auf die Suche nach ihm gemacht, aber ich fürchte, das ist zu viel für ihn. Er ist nicht mehr der Jüngste.\n\nKönnt Ihr ihnen helfen? Wenn Ihr Euch beeilt, trefft Ihr Thaddäus auf der Straße im Norden an.", sourceObjective = "Findet Thaddäus Risswalt bei den Nordpasshöhlen.", completion = "Ich habe mich nicht verirrt! Mein Enkel ist mit seinen Freunden davongelaufen und ich habe sie gesucht. Ich wollte sie vor den Troggs finden!", sourceObjectiveStatus = "unverified-source-field" }
quests[48949] = { id = 48949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kraut aus dem Sumpf", description = "<Magura öffnet nur schwach die Augen, als Ihr Euch nähert.>\n\nHelft... mir... schwach... kann nicht heilen...\n\n<Magura muss sich sehr anstrengen, um mit dem Arm auf eine Pflanze in der Nähe zu zeigen.>\n\nGrabkraut... helft... mehr... bitte...", sourceObjective = "Sammelt 6 Grabkrautzweige aus dem Schreckenssumpf.", sourceObjectiveStatus = "unverified-source-field" }
quests[48951] = { id = 48951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sitz des Triumvirats: Leerenschlund" }
quests[48952] = { id = 48952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochen für alle" }
quests[48953] = { id = 48953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sitz des Triumvirats: Rufer der Dunkelheit" }
quests[48954] = { id = 48954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Blut eines Titanen", description = "<Vor Euren Augen verwandelt sich ein Tropfen Blut des gefallenen Titanen Argus zu einem makellosen Edelstein. Als Ihr ihn in Eurer Hand haltet, spürt Ihr die fast unvorstellbare Macht, die ihm entspringt... ebenso wie Echos von Qualen und Trauer.\n\nEs ist das letzte Überbleibsel einer Schlacht, die nicht zu gewinnen hätte sein sollen. Doch wie alle Siege hatte auch dieser einen enorm hohen Preis.\n\nIhr erkennt sofort, wem Ihr diesen Schatz überbringen solltet.>", sourceObjective = "Bringt das Blut von Argus, dem Zerrütter, zu Khadgar in Dalaran.\n\nBereitgestellter Gegenstand:", completion = "Champion, Ihr seid zurückgekehrt... und gerade noch rechtzeitig.\n\nDer Gegenstand in Euren Händen ist nur eines der vielen Geheimnisse, die uns umgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[48957] = { id = 48957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sitz des Triumvirats: Leerenklinge Zedaat" }
quests[48958] = { id = 48958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritualstörung" }
quests[48959] = { id = 48959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sitz des Triumvirats: Dunkle Spalte" }
quests[48962] = { id = 48962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Telogrusriss", description = "Umbric und seine Blutelfen wurden wegen ihres Wissensdurstes der eigenen Heimat verwiesen.\n\nWenige kennen die Gefahren der Leere besser als ich. Wir sollten ihnen helfen und sie vor leichtsinnigen Fehlern bewahren.\n\nDieser Riss bringt uns zu ihrem derzeitigen Aufenthaltsort. Ich hoffe, unsere Hilfe kommt nicht zu spät.", sourceObjective = "Reist zum Telogrusriss und schließt das Szenario ab.", completion = "Frühere Blutelfen, die sich unserer Sache anschließen wollen. Das ist besser, als ich zu hoffen wagte.", sourceObjectiveStatus = "unverified-source-field" }
quests[48963] = { id = 48963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ablenkungstaktiken", description = "Unser Ziel ist die Hütte da vorn. Sie sieht zwar recht unscheinbar aus, birgt aber dennoch einen großen Teil unserer Geschichte.\n\nAls Erstes müssen wir uns aber um den riesigen Yeti kümmern, der gleich davor sein Lager aufgeschlagen hat. Ich bitte Euch nur ungern darum, aber Ihr müsstet ihn ablenken, damit ich unbemerkt hineingelangen kann.\n\nWenn Ihr ihn erledigt habt, treffen wir uns drinnen.", sourceObjective = "Besiegt Frostkrätze auf der Gebirgshöhe.", completion = "Das war knapp!\n\nIch bin froh, dass Ihr mir als fähige Leibwache dient, {class}. Ich hätte Euch nicht gern zum Feind.", sourceObjectiveStatus = "unverified-source-field" }
quests[48964] = { id = 48964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ass der Unsterblichkeit", description = "<Die Runen der Schriftrollen wandeln sich in eine verständlichere Form.>\n\nEin Bildnis. Der Vielgesichtige benötigt es.\n\nStehlt von den Wichteln. Stehlt von den Unholden. Stehlt von den Ur'zul.\n\nEr kommt.", sourceObjective = "Sammelt Konchen aus der Antorischen Ödnis, um ein Knochenbildnis zu formen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48965] = { id = 48965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine offene Rechnung", description = "Vor einem Jahr hat der größte Eber des Waldes mir meine Tochter genommen.\n\nSeitdem jage ich ihn und immer wieder haben wir gekämpft. Aber dieses Mal...\n\nSagen wir einfach, mir bleibt nicht viel Zeit.\n\nJetzt bleibt mir nur noch das Verlangen nach Rache. Bitte, {class}, rächt uns, damit meine Seele diese Ebene hinter sich lassen kann, um wieder zu meiner Tochter zu finden, wo auch immer sie sein mag.", sourceObjective = "Tötet Kohlhauer in der Fuchsbauwaldung.", completion = "<Karstens Leichnam liegt leblos am Boden. Er ist noch immer warm, doch er erlag während Eurer Abwesenheit seinen Wunden.\n\nAuf seinem Gesicht ruht ein Ausdruck von Zufriedenheit, als hätte er gewusst, dass Ihr seine Bitte erfüllen würdet.>", sourceObjectiveStatus = "unverified-source-field" }
quests[48973] = { id = 48973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion des Argusvorstoßes", description = "Eure Verbündeten im Argusvorstoß haben Eure Anwesenheit erbeten. Sie möchten Euch für Eure unermüdliche Unterstützung eine Belohnung überreichen.", sourceObjective = "Sprecht mit Toraan dem Verehrten auf der Vindikaar.", sourceObjectiveStatus = "unverified-source-field" }
quests[48974] = { id = 48974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion der Armee des Lichts", description = "Eure Verbündeten in der Armee des Lichts möchten Euch für Eure unermüdliche Unterstützung danken. Sie erwarten Euch auf der Vindikaar.", sourceObjective = "Sprecht mit Verteidigerin Jaelaana auf der Vindikaar.", sourceObjectiveStatus = "unverified-source-field" }
quests[48976] = { id = 48976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte des Argusvorstoßes", description = "{class}t, dank Eurer Bemühungen haben unsere Streitkräfte Vorräte entdeckt und sie davor bewahrt, dem Feind in die Hände zu fallen.\n\nDurch Eure fortwährende Unterstützung werden wir weitere Ressourcen anbieten können.", sourceObjective = "Sprecht mit Toraan dem Verehrten auf der Vindikaar.", completion = "Schlachtenfürst, danke für Eure Mühen. Unsere Truppen konnten dadurch weitere Ressourcen auf dem Schlachtfeld sicherstellen.\n\nJe deutlicher Ihr das Schlachtfeld beherrscht, desto mehr Ressourcen können unsere Truppen erübrigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48977] = { id = 48977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Armee des Lichts", description = "Archenon poros, Champion.\n\nDie Armee des Lichts möchte Euch für Eure Hilfe im Kampf gegen die Legion auf Argus danken.\n\nBitte nehmt diese Vorräte zusammen mit unserer tiefen Dankbarkeit an. Mit Eurer unermüdlichen Unterstützung kommen wir unserem Ziel, die Legion ein für alle Mal zu vernichten, jeden Tag etwas näher.", sourceObjective = "Sprecht mit Verteidigerin Jaelaana auf der Vindikaar, um Eure Belohnung zu erhalten.", completion = "Archenon poros, Champion.\n\nDie Armee des Lichts möchte Euch für Eure Hilfe im Kampf gegen die Legion auf Argus danken.\n\nBitte nehmt diese Vorräte zusammen mit unserer tiefen Dankbarkeit an. Mit Eurer unermüdlichen Unterstützung kommen wir unserem Ziel, die Legion ein für alle Mal zu vernichten, jeden Tag etwas näher.", sourceObjectiveStatus = "unverified-source-field" }
quests[48982] = { id = 48982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasionspunkt: Aurinor" }
quests[48983] = { id = 48983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergbauregeln" }
quests[48985] = { id = 48985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sitz des Triumvirats: Zwielichtbote Tharuul" }
quests[48986] = { id = 48986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Aroms Wehr", description = "Wir müssen weiter nach Aroms Wehr. Es wird eine Weile brauchen, das Wissen des Folianten zu analysieren und weitere Inquisitoren im Dienste unserer Sache auszubilden.\n\nWenn die Waffen des Ordens im Kampf gegen den Zirkel so effektiv sind wie gegen die Drust, könnte es uns gelingen, meine Familie zu retten und das Land zu vormaliger Blüte zu führen.\n\nIch werde mich zu Fuß auf den Weg dorthin machen. Auf ein baldiges Wiedersehen, {class}.", sourceObjective = "Trefft Luzilla Kronsteig bei Aroms Wehr in Drustvar.", completion = "Ich bin froh, dass Ihr es geschafft habt, {name}. \n\nWir müssen sofort beginnen, wenn wir das in diesem Folianten enthaltene Wissen gegen den Zirkel verwenden wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48987] = { id = 48987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Kummertal", description = "Die Erinnerung'n Eurer Freundin sind fort. \n\nDas is' Akundas Gabe an uns. Er nimmt die schmerzhaften Erinnerungen, aber in letzter Zeit geht deutlich mehr verlor'n. \n\nIch weiß nich' ma', was ich zum Frühstück hatte. Und das wird jeden Tag schlimmer. \n\nDa stimmt was nich'. \n\nMeijani und ich hatten 'nen Plan. Wir wollt'n... irgendwas... im Kummertal tun. Dort bewahrt Akunda die vergess'nen Erinnerung'n auf. \n\nWenn Ihr Antworten sucht, solltet Ihr zuerst Meijani such'n.", sourceObjective = "Findet Meijani im Kummertal.", completion = "Wer seid Ihr? Kenn' wir uns?", sourceObjectiveStatus = "unverified-source-field" }
quests[48988] = { id = 48988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erinnerungslücke", description = "In diesem Tal lieg'n die Erinnerung'n von Akundas Anhängern. \n\nDie meist'n sollt'n wohl verlor'n bleiben, aber nur durch sie könn' wir erfahr'n, was mit Akunda passiert is'. \n\nSeht Euch die Erinnerung'n hier an. Sucht nach Hinweisen darauf, was unsrem Loa zugestoß'n is'. \n\nIch warn' Euch, das is' keine Aufgabe für Schwächlinge. Was man in diesen Erinnerung'n erblickt, wird man nich' wieder los.", sourceObjective = "Sucht nach Hinweisen in unerwünschten Erinnerungen.", completion = "Das hatt' ich befürchtet. Man hat dem Loa seine eignen Erinnerung'n genomm'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[48991] = { id = 48991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Widerlicher Befall", description = "Erlösung muss man sich erst verdien'. \n\nWir tun Gutes, um Akunda zu zeig'n, dass wir seinen Segen verdien'. \n\nDie Ranishu sind wie 'ne Seuche für dieses Land. Sie fress'n alles, was sie krieg'n können, ganz gleich, wie's schmeckt oder aussieht. \n\nWenn das so weitergeht, ham sich diese widerlich'n Schädlinge bald bis zum Tempel durchgefress'n.\n\nBefreit die Ebene von ihnen. Zeigt Akunda, dass Ihr seine Gabe verdient.", sourceObjective = "Tötet 12 Ranishu im Rotfelstal.", completion = "Akunda is' Euch wohlgesonn'n. Er weiß, was Ihr hier heute getan habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[48992] = { id = 48992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilige Überreste", description = "Das Gebiet war einst 'n üppiger Dschungel und Heimat vieler großer un' mächtiger Donnerechs'n.\n\nDie Knoch'n dieser uralt'n Kreatur'n kann man noch immer im Bod'n rund um den Tempel find'n.\n\nVon dies'n uralt'n sterblich'n Überrest'n geht noch große Macht aus... Um Akunda zu ruf'n, braucht Ihr solche Macht.\n\nDurchkämmt das Gebiet un' bringt mir die uralt'n Knoch'n der Donnerechs'n.", sourceObjective = "Sammelt 6 heilige Überreste.", progress = "Habt Ihr die uralten Knochen gefund'n?", completion = "Diese Knoch'n sind immer noch voll Macht.", sourceObjectiveStatus = "unverified-source-field" }
quests[48993] = { id = 48993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Machtvolle Leiter", description = "Akunda bietet uns die Chance auf 'nen Neuanfang. \n\nDer Loa dringt durch 'n heiliges Ritual in unsren Verstand ein un' entfernt die schmerzend'n Erinnerung'n. \n\nWenn Ihr den Segen von Akunda wollt, müsst Ihr Euch fürs Ritual vorbereit'n. \n\nDie Schädlinge, die die ganz'n Wildtiere hier fress'n, ham Fühler, die Magie besonders gut leit'n könn'. Je größer, desto besser. \n\nMit den Fühlern vom Anführer könnt's funktionier'n. Er is' mindestens dreimal so groß wie 'n normaler Ranishu.", sourceObjective = "Beschafft Rorgogs Antennen.", progress = "Habt Ihr die Fühler?", completion = "Ja... damit wird's klappen.", sourceObjectiveStatus = "unverified-source-field" }
quests[48996] = { id = 48996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende des Wahnsinns", description = "Akunda der Erhabene ist nicht der, für den Ihr ihn haltet. \n\nEr hat den Ewigen Quell vergiftet, sodass alle, die davon tranken, krank wurden. Nicht einmal ich war gegen seine abscheuliche Alchemie immun. \n\nNun entzieht er mir meine Macht und nutzt meine Gabe, um den Verstand all jener zu löschen, die ihn aufhalten könnten. \n\nWir werden ihm den Erfolg verwehren. \n\nIch werde Euch das bisschen Macht geben, das mir bleibt. \n\nRuft damit den Sturm und beendet den Wahnsinn, der meinen Tempel ergriffen hat.", sourceObjective = "Besiegt Akunda den Erhabenen.", completion = "Ihr geht mit meiner Gabe gut um, {name}. \n\nNun, wo meine Macht zurück ist, kann ich die Geister meiner Kinder heilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49001] = { id = 49001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbequeme Geister", sourceObjective = "Tötet 8 gepeinigte Geister.", completion = "Hmm, also wenn es ums Töten geht, seid Ihr echt ein Profi. Das konnte ich selbst von hier aus sehen. Willkommen im Team.", sourceObjectiveStatus = "unverified-source-field" }
quests[49002] = { id = 49002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erzwungene Landung", description = "<Das ist einer der Speere, mit denen treulose Fallensteller Pterrordaxe zu Boden ziehen. An seinem Ende ist eine lange Kette befestigt.\n\nWenn Ihr gut zielt, könntet Ihr damit einen treulosen Pterrordaxreiter zu Boden ziehen, um gegen ihn kämpfen zu können.>", sourceObjective = "Benutzt den Speer des treulosen Fallenstellers, um den Pterrordax von Giftzahnrufer Hrillik vom Himmel über Euch zu Boden zu ziehen und ihn zu töten.", progress = "<Rakjan hebt stolz seinen Kopf.>", completion = "<Rakjan nickt Euch anerkennend zu. Ein Giftzahnrufer weniger, um den Ihr Euch sorgen müsst.>", sourceObjectiveStatus = "unverified-source-field" }
quests[49003] = { id = 49003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache von oben", description = "Imperator Korthek versteckt sich tief in seinem eroberten Tempel unter der Erde. Wir müssen solch ein Chaos auslösen, dass ihm keine andere Wahl bleibt, als sich uns zu stellen.\n\nDer Aufstand der Vulpera ist ein guter Anfang, doch er wird nicht reichen. Allein kommen sie gegen keine Armee der Treulosen an.\n\nGlücklicherweise sind sie nicht alleine.\n\nWir werden auf dem mächtigen Rakjan durch den Himmel reiten. Während Ihr Blitzbomben werft, werde ich mit meinem geladenen Stab die Armeen der Treulosen unter uns beschießen.\n\nLasst uns hoffen, dass es reicht, um Korthek herauszulocken. Ich will es endlich hinter mich bringen.", sourceObjective = "Reitet auf Rakjan dem Ungebrochenen und tötet Treulose.", completion = "Imperator Korthek ist inzwischen sicher auf dem Weg zu uns. Wir müssen uns schnell vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[49005] = { id = 49005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zersplittert und zerbrochen", description = "Irgendwas stimmt hier nich'. \n\nUnerwüschte Erinnerung'n wurd'n aus ihren magischen Banden entlass'n. \n\nAkundas Macht soll sie eigentlich wegsperr'n...\n\nDie Verkörperungen unsrer schrecklichsten Erinnerung'n ham in dieser Welt nix zu such'n. \n\nDie müss'n vernichtet werd'n.", sourceObjective = "Tötet zersplitterte und verzerrte Erinnerungen.", completion = "Ihr habt das Richtige getan. Solche Erinnerung'n hab'n in unser Welt nix zu such'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[49007] = { id = 49007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommandant an Deck!", description = "<Das Gerät springt mit einem Summen an, bereit, Euch zum Portal von Schwadronskommandant Vishax in der Antorischen Ödnis bringen.>", sourceObjective = "Benutzt Vishax' Portal.", sourceObjectiveStatus = "unverified-source-field" }
quests[49013] = { id = 49013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein mächtiger Schock", description = "Euch habe ich zu verdanken, dass dieser Thronräuber beseitigt ist.\n\nMeine Kraft kehrt allmählich zurück, aber leider haben meine Kinder bereits Schaden genommen.\n\nSie sind schwach und sterben. Ihr müsst sie wiederherstellen.\n\nMein Segen wird Euch Macht über die Stürme verleihen.\n\nNutzt sie, um meine Kinder zu retten, wie Ihr mich gerettet habt.", sourceObjective = "Nutzt den 'Segen von Akunda', um Sturmechsen wiederzubeleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[49014] = { id = 49014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Brennende Thron", description = "Die Zeit ist gekommen, {name}, um unseren Angriff auf Antorus zu starten. Alles, wofür wir gekämpft haben, all die Opfer unserer Freunde und Familien, haben uns an diesen Punkt geführt.\n\nWir werden mit dem Urteil des Lichts auf die Mauern dieser verfluchten Zitadelle feuern und ihr Machtzentrum erstürmen. Wir werden der Legion ein Ende setzen.\n\nNach all Euren Taten ist es nur recht und billig, dass Euch diese Ehre zuteil wird. Sprecht mit Romuul und lasst uns die Mission zu Ende bringen.", sourceObjective = "Sprecht mit Großkonstrukteur Romuul über der Antorischen Ödnis und öffnet den Weg nach Antorus.", completion = "Nach so vielen Jahren... so vielen Opfern... ist der Sieg endlich in Reichweite.", sourceObjectiveStatus = "unverified-source-field" }
quests[49015] = { id = 49015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antorus, der Brennende Thron: Der Tod eines Titanen", description = "Ich vermag es nicht, meine Trauer und meine Wut über Sargeras Taten zum Ausdruck zu bringen.\n\nMeine Heimatwelt Argus enthält die Seele eines Titanen. Die Verderbnis hat sie durchwachsen und eine Erlösung ist nun unmöglich. Ihre Macht treibt die endlose Armee der Legion an.\n\nWir müssen das Unmögliche vollbringen... in die Tiefen von Antorus dringen und die Verbindung zwischen Legion und Weltenseele trennen.\n\nBitte, {name}. Setzt ihrem Leiden ein Ende. Wenn wir das düstere Herz von Argus zerschlagen, wird auch die Legion erliegen... und die Seele meiner Welt wird erlöst sein.", sourceObjective = "Bezwingt die Seele von Argus in Antorus, dem Brennenden Thron.", completion = "Endlich, es ist vollbracht. Der Brennende Kreuzzug ist beendet.\n\nIch danke Euch für alles, was Ihr geleistet habt, {name}. Solange die Macht von Argus Sargeras' Dunkles Pantheon erfüllt hat, war er unaufhaltsam.\n\nIm Namen all der Draenei, der Eredar und der endlosen Welten, die der Legion erlegen sind...\n\nHabt Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[49027] = { id = 49027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gelegenheitsziele: Der Terminus", description = "Diese Legionsschiffe stellen ein Problem dar, {name}.\n\nSie docken bedrohlich nahe an der Vindikaar und bedrohen uns allein durch ihre Gegenwart.\n\nIm Kampf gegen die Legion ist es manchmal besser, gleich an die Spitze zu gehen, anstatt ihre Reihen auszudünnen.\n\nBegebt Euch zu den Werften von Terminus und tötet ihre Offiziere und Kommandanten. Das sollte ihre Truppen erschüttern und zurück in die Defensive drängen." }
quests[49028] = { id = 49028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Pulli für Rupert", description = "In dieser Gegend werden die Nächte richtig kalt und ich befürchte, dass mein armer Hund erfrieren könnte. Ich möchte ihm einen Pullover nähen, doch mir fehlen dazu Materialien.\n\nWer mir ein paar Stachelrattenstacheln und vier Waschbärschwänze bringt, erhält eine großzügige Belohnung.\n\n- Kolta", sourceObjective = "Beschafft Koltas Materialien.", progress = "Braucht Ihr etwas von mir?", completion = "Ich danke Euch, mein Hund und ich stehen ewig in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[49029] = { id = 49029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbeugende Maßnahmen", description = "Wir befinden uns auf der Heimatwelt der Legion und dürfen uns nicht überraschen lassen.\n\nDiese Invasionspunkte können ihre Streitkräfte unterstützen und unsere Pläne durchkreuzen. Wenn wir sie in ihrem Gebiet bezwingen, schaden wir auch ihrer Organisation und ihrer Infrastruktur.\n\nTötet ihre Befehlshaber und haltet die Invasionstruppen auf. Jetzt beginnt der Kampf, um die Legion zurückzudrängen!" }
quests[49030] = { id = 49030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragmente aus dem Abyss", description = "Unsere Kundschafter haben Verstörendes berichtet, Champion.\n\nEinige der mächtigeren Leerenkreaturen tragen Kristalle bei sich, die ihre Fähigkeiten weiter verstärken. Jetzt sind sie eine noch größere Bedrohung als zuvor und wir können uns nicht mehr erlauben, sie zu ignorieren.\n\nFindet diese leerenverseuchten Monstrositäten und entreißt ihnen die Kristalle. Wir kümmern uns derweil um eine Methode, wie wir sie sicher beseitigen können." }
quests[49031] = { id = 49031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inquisitoren raus", description = "Unter all den Dämonen im Dienste der Legion gehören die Inquisitoren zu den schrecklichsten.\n\nSelbst die geringeren Dämonen fürchten sich vor ihnen. Diese Monster genießen es, ihre Gefangenen grausam zu quälen.\n\nDer Schrecken, den die Inquisitoren verbreiten, erfüllt sie, doch vielleicht können wir uns das zunutze machen.\n\nFindet die mächtigsten Inquisitoren und bezwingt sie. Ihre Tode werden nicht nur die Moral unserer Truppen stärken, sondern auch ihren geringeren Einheiten eine Lehre sein." }
quests[49032] = { id = 49032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antorus, der Brennende Thron: Dunkle Passage", description = "Trotz der bedrohlichen Energien, die aus dem Herz von Argus strömen, reist der Seelenjäger ungehindert durch den Brennenden Thron. Unsere Kundschafter berichten, dass sein Gefährt die Macht dämonischer Runen nutzt, um die Hochheiligen Teufelswerke sicher zu erreichen.\n\nWenn wir diese Runen beschaffen, könnte die Vindikaar denselben Weg einschlagen. Dadurch würden unsere Streitkräfte kostbare Zeit gewinnen.", sourceObjective = "Sammelt 4 Passierrunen von Imonar dem Seelenjäger in Antorus, dem Brennenden Thron, auf dem Schwierigkeitsgrad 'Normal'.", progress = "Ohne die Runen müssen wir uns direkt auf Sargeras' Armee stürzen.", completion = "Ausgezeichnete Arbeit!\n\nSobald diese Runen in unsere Schildmatrix integriert sind, kann die Vindikaar die Verteidigung des Brennenden Throns umgehen und direkt bei den Teufelswerken zuschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49033] = { id = 49033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "NEU VERWENDEN" }
quests[49036] = { id = 49036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meisterleistung", description = "Jetzt, da die Troggs beseitigt wurden, können wir mit der echten Show beginnen!\n\nIhr habt Euch wahrlich als <fähiger Reiter/fähige Reiterin> bewiesen. Seid Ihr bereit, einfach alles zu geben?\n\nSchaut doch mal, ob Ihr dreihundert Punkte erreichen könnt!", sourceObjective = "Steigt auf Böttcher auf, um mit Eurer Show zu beginnen, und erzielt mindestens 300 Punkte.", completion = "Was für eine Darbietung!", sourceObjectiveStatus = "unverified-source-field" }
quests[49039] = { id = 49039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Beginn einer Monsterjagd", description = "So nahe war ich noch nie an einem Leichnam, wie aufregend! Was ihn wohl umgebracht hat?\n\nWie dem auch sei, es ist meine Pflicht, die Sicherheit meiner Angestellten zu gewährleisten. Mit Scharfsinn, Heldenmut und Euren praktischen Fertigkeiten werden wir sicher herausfinden, was passiert ist.\n\nDavon wird man sich noch lange Zeit am Lagerfeuer erzählen.\n\nSchauen wir uns erst mal am Lager nach Hinweisen um.", sourceObjective = "Untersucht die Trümmer des Lagers.", completion = "Eine Spur, sagt Ihr? Wo die wohl hinführt...", sourceObjectiveStatus = "unverified-source-field" }
quests[49040] = { id = 49040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herzlicher Abschied", description = "Hier trenn' sich unsre Wege, {name}.\n\nIch werd den Namen Akunda trag'n un' hier 'n neues Leb'n anfang'n. \n\nWenn Ihr Rakera findet, und das werdet Ihr, dankt ihr von mir. \n\nSie hat mir das Leb'n gerettet, und ich will ab jetzt 'n Leb'n führ'n, was es auch wert war, gerettet zu werd'n. \n\nKönnt Ihr vielleicht diese Nachricht für mich übergeb'n, wenn Ihr ma' wieder in der Stadt seid? Ich vertrau drauf, dass Ihr sie nich' aufmacht, obwohl ich echt nich' glaub, dass Ihr meine Sauklaue überhaupt entziffern könnt.", sourceObjective = "Liefert Joraks Nachricht bei B'wizati in Zuldazar ab.", progress = "Was is' das?", completion = "<B'wizati liest die Nachricht und wischt sich eine Träne aus dem Gesicht.>\n\nVielleicht kann er vergess'n, aber ich will mich erinnern, auch wenn's noch so schmerzt. \n\nWenigstens is' er in Sicherheit. Der Loa wacht über ihn.", sourceObjectiveStatus = "unverified-source-field" }
