quests[49058] = { id = 49058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einer-von-vielen" }
quests[49059] = { id = 49059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Knochen von Xibala", description = "Unsere Verbündeten in der Forscherliga haben uns auf einen aufregenden Fund aufmerksam gemacht. Sie haben ein Lager in der Region Xibala in Zuldazar aufgeschlagen.\n\nBegebt Euch zu dem Lager und helft ihnen dabei, alles zu finden, das unsere Sache voranbringen könnte.", sourceObjective = "Reist nach Xibala und trefft Euch mit Acadia Tistelstein.", sourceObjectiveStatus = "unverified-source-field" }
quests[49060] = { id = 49060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tierpopulation von Xibala", description = "Ich und meine Jungs wollen endlich da raus und unsere Spitzhacken schwingen, aber jeder Späher, den wir in die Ruinen geschickt haben, ist halbtot und in Fetzen zurückgekommen.\n\nEinige sind gar nicht zurückgekehrt.\n\nSo, wie ich das sehe, beherbergen diese Ruinen mehr als nur diese stachligen Grasfresser. Seid doch ein Schatz und dünnt die Population etwas aus, ja?\n\nIch würde zwar zur Vorsicht raten, wenn Ihr in die hiesige Umwelt hineinpfuscht, aber da ich keine Lust habe, gefressen zu werden, überlasse ich Euch die Entscheidung.", sourceObjective = "Tötet 12 Raubtiere von Xibala.", completion = "Ich bin froh, dass ich nicht dort war, aber hier ist eine kleine Belohnung für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49064] = { id = 49064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torga, der Schildkrötenloa", description = "Mein Name ist Lashk. Wir sind nicht hier, um uns irgendeiner Sache anzuschließen, sondern wollen nur Torgas legendäre Geschichten hören.\n\nIch weiß nicht, ob er dazu bereit ist, aber Ihr könnt ja versuchen, Torga, den Loa der Schildkröten, zu überzeugen, Euch im Kampf gegen die Bluttrolle zu helfen.\n\nIhr könnt Euch unserer Pilgerreise zu Torga anschließen, aber verhaltet Euch ruhig. Wenn Ihr diesem Pfad folgt, findet Ihr Kisha. Sie wird Euch sagen, wohin Ihr gehen müsst.", sourceObjective = "Folgt dem Pfad der tortollanischen Pilger, um zu Torga, dem Loa der Schildkröten, zu gelangen.", completion = "Das is' das Werk von Bluttrollen, das kann ich riech'n. Wir geh'n dieser Sache aufn Grund.", sourceObjectiveStatus = "unverified-source-field" }
quests[49066] = { id = 49066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gut gekühlt", description = "Das glasklare Eis am Fuße der hiesigen Klippen und besonders die dafür verantwortlichen Elementare sind wohlbekannt. Die Jäger in meiner Hütte benutzen die Splitter aus ihren Körpern, um ihre Vorräte für den Transport einzufrieren.\n\nUnd noch viel wichtiger, denkt nur, wie hilfreich das für Getränke wäre!\n\nSchauen wir mal, ob wir ein paar Elementare finden und ihre Splitter sammeln können.", sourceObjective = "Sammelt 20 makellose Eisbrocken von Eiselementaren.", progress = "Es macht sie angeblich wütend, wenn jemand die größeren Eisskulpturen in der Gegend zerstört, also bemüht Euch, so viele zu zerstören, wie Ihr finden könnt!", completion = "Perfekt gekühlte Getränke erwarten mich! Und es sollte auch für die Jäger ausreichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49067] = { id = 49067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bitte an Bwonsamdi", description = "Wir müss'n mit Torgas Geist sprech'n un' herausfind'n, was hier genau passiert is'... un' wie wir die Sache aufhalt'n könn'.\n\nIhr sagt, Ihr habt jetzt 'ne Verbindung zu Bwonsamdi?\n\nDann müss'n wir diese Verbindung jetzt nutz'n un' Bwonsamdi bitt'n, uns Torgas Geist zu hol'n.", sourceObjective = "Beschwört Bwonsamdi und bittet ihn um Hilfe.", completion = "Was auch immer daraus werd'n wird, wir hab'n jetzt Bwonsamdis Hilfe. Mach'n wir uns ans Töt'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[49068] = { id = 49068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ordnung in der Bucht" }
quests[49069] = { id = 49069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Alte Frostklaue", description = "Die alte Frostklaue wurde wieder einmal am Rand des Passes erblickt. Jägern wird empfohlen, diesen Bereich nur mit Vorsicht zu betreten. Sie ist größer als ein gewöhnlicher Bär und hat schon vier Leute auf dem Gewissen. Es würde mich betrüben, wenn sie einen der unseren zum fünften Opfer macht.\n\nWer auch immer diese Bestie tötet, wird unabhängig von seinem oder ihrem Beruf belohnt.\n\n- Alina \n\n<Unter der Unterschrift der Meisterschützin befindet sich eine kindliche Zeichnung mit den Worten \"alte Frostklaue\" darüber.>", sourceObjective = "Tötet die alte Frostklaue.", completion = "Ich werde die Jäger wissen lassen, dass ihnen ein Durchreisender die Beute weggeschnappt hat. Das sollte einige von ihnen auf den Boden der Tatsachen zurückbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49070] = { id = 49070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelen für den Todesloa", description = "Da wimmelt's nur so von Bluttrollen. Die nehm' Torga komplett aus. Sie fress'n sogar sein Fleisch.\n\nSogar ich find das schlimm. \n\nDie Seel'n dieser Bluttrolle sind verderbt, weil sie 'nen Loa gefress'n ham. Das solltet Ihr Euch für die Zukunft merk'n.\n\nDiese Seel'n bedeut'n mir sehr viel, viel mehr als nur die normal'n Seel'n der Bluttrolle. \n\nBeschafft mir die verderbt'n Seel'n dieser Bluttrolle un' ich werd für Euch Torgas Geist ruf'n.", sourceObjective = "Beschafft 10 Bluttrollseelen aus Torga.", progress = "Ihr habt noch nich' genug Bluttrolle getötet!", completion = "Gut! Ich werd' mir jetzt all ihre Seelen hol'n!", sourceObjectiveStatus = "unverified-source-field" }
quests[49071] = { id = 49071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explodierende Sauger", description = "Diese ganze Sache ist doch total verrückt, oder? So etwas Widerliches könnte man sich ja gar nicht ausdenken...\n\nBäh! Hört Ihr auch diese unerträglichen Geräusche?\n\nDas sind diese ekligen Schreckenszecken, die sich an Torgas Fleisch laben. Das ist so widerwärtig!\n\nWas? Ihr könnt es gar nicht hören? Aber glaubt mir, sie sind da und jemand muss sich um sie kümmern.\n\nHier, nehmt diese Schriftrolle. Wir hatten schon früher mit diesen Insekten zu tun. Wenn Ihr die Schriftrolle in ihrer Nähe lest, werden sie explodieren.", sourceObjective = "Jagt 5 Schreckenszeckensauger mithilfe von LashksSchriftrolle der Verbrennung in die Luft.", completion = "Es geht mir schon viel besser, wenn ich weiß, dass es weniger von diesen... Viechern gibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[49072] = { id = 49072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adliger gen Westen", description = "Es ist mir ein Gräuel, Euch noch weiter in diese Sache hineinzuziehen, doch ich habe nicht genügend Männer, um Lord Kenninger eine Eskorte zu geben. Wenn er verletzt wird, können wir uns alle eine neue Beschäftigung suchen. Könnt Ihr sicherstellen, dass er es zumindest bis zum westlichen Lager schafft?", sourceObjective = "Findet Lord Kenninger.", completion = "Oh, da seid Ihr endlich! Ich glaube, wir haben ernstere Probleme als nur die Hirschjagd.", sourceObjectiveStatus = "unverified-source-field" }
quests[49073] = { id = 49073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritualus Interruptus", description = "Ich kann nicht glauben, dass wir es mit einem Toten-Loa, einem TOTEN Loa und Bluttrollen zu tun haben. Für heute hatte ich nämlich ganz andere Pläne!\n\nAlso, ein paar der anderen Tortollaner haben die Blutrituale beobachtet. Sie sind in Panik geraten und an die Küste geflüchtet, als sie sie gesehen haben.\n\nNehmt diese Schriftrolle und lest sie laut vor, wenn Ihr Euch in der Nähe von Blutritualen aufhaltet. Damit solltet Ihr sie unterbrechen können.\n\nUnd passt gut auf meine Schriftrolle auf! Sie ist sehr alt und heutzutage bekommt man so etwas gar nicht mehr.", sourceObjective = "Unterbrecht 3 Blutrituale mithilfe von Kishas Schriftrolle der Reinigung.", sourceObjectiveStatus = "unverified-source-field" }
quests[49075] = { id = 49075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antorus, der Brennende Thron: Dunkle Passage", description = "Trotz der bedrohlichen Energien, die aus dem Herz von Argus strömen, reist der Seelenjäger ungehindert durch den Brennenden Thron. Unsere Kundschafter berichten, dass sein Gefährt die Macht dämonischer Runen nutzt, um die Hochheiligen Teufelswerke sicher zu erreichen.\n\nWenn wir diese Runen beschaffen, könnte die Vindikaar denselben Weg einschlagen. Dadurch würden unsere Streitkräfte kostbare Zeit gewinnen.", sourceObjective = "Sammelt 4 Passierrunen von Imonar dem Seelenjäger in Antorus, dem Brennenden Thron, auf dem Schwierigkeitsgrad 'Heroisch'.", progress = "Ohne die Runen müssen wir uns direkt auf Sargeras' Armee stürzen.", completion = "Ausgezeichnete Arbeit!\n\nSobald diese Runen in unsere Schildmatrix integriert sind, kann die Vindikaar die Verteidigung des Brennenden Throns umgehen und direkt bei den Teufelswerken zuschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49076] = { id = 49076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antorus, der Brennende Thron: Dunkle Passage", description = "Trotz der bedrohlichen Energien, die aus dem Herz von Argus strömen, reist der Seelenjäger ungehindert durch den Brennenden Thron. Unsere Kundschafter berichten, dass sein Gefährt die Macht dämonischer Runen nutzt, um die Hochheiligen Teufelswerke sicher zu erreichen.\n\nWenn wir diese Runen beschaffen, könnte die Vindikaar denselben Weg einschlagen. Dadurch würden unsere Streitkräfte kostbare Zeit gewinnen.", sourceObjective = "Sammelt 4 Passierrunen von Imonar dem Seelenjäger in Antorus, dem Brennenden Thron, auf dem Schwierigkeitsgrad 'Mythisch'.", progress = "Ohne die Runen müssen wir uns direkt auf Sargeras' Armee stürzen.", completion = "Ausgezeichnete Arbeit!\n\nSobald diese Runen in unsere Schildmatrix integriert sind, kann die Vindikaar die Verteidigung des Brennenden Throns umgehen und direkt bei den Teufelswerken zuschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49077] = { id = 49077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Momente der Reue", description = "<Der Kristall ruft Euch und vibriert vor Magie.\n\nAls Ihr ihn anfasst, hört Ihr das Echo einer vergangenen Nachricht, eine Aufgabe, die Illidan Euch anvertraut hat.>", sourceObjective = "Bringt Illidans Kristall zu den Personen und Orten, die ihm am meisten am Herzen liegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49078] = { id = 49078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brut vergiften", description = "Jetzt können wir uns darum kümmern, Hir'eek zu erledig'n. Also, {name}, ich bin ja Spezialist für Gifte un' Tränke.\n\nIch hab an 'nem Gift für Hir'eek gearbeitet, um es bereit zu ham, wenn die Zeit gekommen is', aber ich weiß nich', ob es funktioniert.\n\nIch will, dass Ihr mit dem, was ich schon gemacht hab, loszieht un' ein paar Fledermäuse in der Gegend tötet. Es sollte sie sofort umbring'n. \n\nWenn es funktioniert, kann ich es mit meinem Voodoo noch stärker mach'n. Dann können wir damit vielleicht sogar Hir'eek töt'n.", sourceObjective = "Verwendet das Fläschchen mit vergiftetem Mojo, um 5 der gezähmten Kriegsbrut zu vergiften.", completion = "Ich wusste, dass mein Gift wirk'n würde! Ich muss nur noch 'n bisschen mehr Voodoo reinpack'n un' dann taugt es auch für Hir'eek.", sourceObjectiveStatus = "unverified-source-field" }
quests[49079] = { id = 49079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hir'eek, der Fledermausloa", description = "Hir'eek weiß, dass wir da sin'. Wenn es stimmt, was ich über Hir'eek gehört habe, wird er uns persönlich töt'n woll'n, sobald wir uns zeig'n.\n\nDer Zeitpunkt is' gekomm'. Wir beide geh'n da raus un' tret'n vor eine Horde Bluttrolle, die seh'n woll'n, wie ihr Loa uns tötet.\n\nNehmt den Dolch. Er is' mit Gift überzog'n, das ich selbst gemacht hab. Ihr werdet wahrscheinlich länger überleb'n als ich und könnt ihn dann einsetz'n.\n\nTut so, als würdet Ihr vor Hir'eek kauern, und überlasst mir das Red'n. Un' auf mein Signal hin springt Ihr dann los un' stecht auf Hir'eek ein!\n\n...un' dann hoffen wir auf das Beste.", sourceObjective = "Stellt Hir'eek mithilfe von Jo'chunga.", completion = "<Hust.> Tja... Zumindest hab ich mir nich' das Rückgrat gebroch'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[49080] = { id = 49080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende aller Beschwörungen", description = "Ich spüre, dass im Innern von Torga was Dunkles un' Mächtiges heraufbeschwor'n wird. Ihr müsst das aufhalt'n!\n\nEs muss eine Beschwörerin geb'n, die Torgas Blut missbraucht, um 'ne Art Ritual durchzuführ'n.\n\nIhr müsst das unbedingt stopp'n. Ich werde hier bleib'n un' diese Tortollaner vor den Bluttrollen beschütz'n.", sourceObjective = "Tötet Beschwörerin Yarz.", progress = "Habt Ihr die Beschwörerin getötet?", completion = "Wir sin' zu spät? Dann könn'n wir nur hoff'n, dass Torga uns helf'n kann, das zu vernicht'n, was Ihr da geseh'n habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[49081] = { id = 49081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod eines Loas", description = "Ich bin ziemlich schwer verletzt... Ich glaub, ich kann mich nich' beweg'n. Keine Sorge, ich hab 'n paar Tränke, die mich heil'n... aber das dauert.\n\nHir'eek is' in der Halle da hinten. Das Gift hat ihn geschwächt, aber er is'n Loa un' es wird ihn noch lange nich' töt'n.\n\nIch kann nich' glaub'n, dass wir... dass IHR 'n Loa töt'n werdet. So was mach'n wir einfach nich', aber Hir'eek is' jetzt 'n Diener von G'huun un' wir ham keine Wahl!\n\nJetzt liegt es an Euch. Tötet Hir'eek un' beendet diesen Wahnsinn!", sourceObjective = "Besiegt Hir'eek, den Loa der Fledermäuse.", progress = "Hir'eek is' noch am Leben! Tötet ihn!", completion = "Ich weiß. Es ging nich' anders. Hir'eek is' tot. Nazmir is'n verfluchter Ort, {name}. Wir hätt'n nie 'nen Loa töt'n soll'n... Aber das hab'n wir.", sourceObjectiveStatus = "unverified-source-field" }
quests[49082] = { id = 49082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rauf und immer weiter", description = "Traurig, dass Hir'eek sterb'n musste, aber zumindest sin' die Bluttrolle jetz' geschwächt.\n\nMeine Tränke heil'n mich gut. Ich hab mich etwas umgeschaut un' den hier gefund'n.\n\nEr is'n bisschen wild, aber nich' feindselig. Ich denk, mit ihm könntet Ihr hier rauskomm'.\n\nSpringt schnell auf, bevor er das Seil zerreißt! Un' keine Sorge um mich. Ich find selbst hier raus.", sourceObjective = "Kehrt zu den Ruinen von Zo'bal zurück und erzählt Hexendoktor Kejabu, was geschehen ist.", completion = "Tut mir leid. Ihr habt getan, was Ihr tun musstet... Ich hätt nich' geglaubt, dass dieser G'huun ausgerechnet 'nen Loa verderb'n könnte.\n\nNazmir is'n verfluchter Ort... für alle.", sourceObjectiveStatus = "unverified-source-field" }
quests[49091] = { id = 49091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasionspunkt: Val" }
quests[49096] = { id = 49096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasionspunkt: Naigtal" }
quests[49097] = { id = 49097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasionspunkt: Sangua" }
quests[49098] = { id = 49098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasionspunkt: Cen'gar" }
quests[49099] = { id = 49099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasionspunkt: Bonich" }
quests[49120] = { id = 49120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit den Toten sprechen", description = "Ihr habt Euren Teil unsrer Abmachung eingehalt'n, also zeig ich Euch, was von Torgas Seele übrig is'.\n\nDafür brauch ich 'nen kleinen Teil von Euch als Leitung, um Torga zu beschwör'n. Keine Sorge, Ihr erhaltet alles zurück.\n\nDas Meiste.\n\nDanach mach ich mich auf'n Weg. Ihr könnt mich jederzeit wieder ruf'n... aber nur, wenn Ihr mir 'n neues Geschäft vorschlag'n könnt.", sourceObjective = "Bittet Bwonsamdi, Torgas Geist heraufzubeschwören.", progress = "Seid Ihr bereit, mit Torgas Geist zu red'n?", completion = "Wir krieg'n vielleicht nicht Torgas Hilfe, aber wir können die Bluttrolle und ihre Pläne aufhalt'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[49122] = { id = 49122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Hafen in Not", description = "Eine Gruppe Mogu hat sich im Kriegshafen der Rastari breitgemacht und droht jetzt damit, in meine Stadt vorzurück'n.\n\nMan könnt meinen, Zul hätt seine Haustiere nicht mehr im Griff. \n\nDieser Hafen ist für unsere Kriegsflotte unentbehrlich. Wenn diese Rohlinge Erfolg ham, wird Zuldazar fall'n und es wird keine Flotte mehr geb'n, die Eurer geliebt'n Horde helf'n könnte.\n\nIhr wollt Eure Verbundenheit mit den Zandalari beweis'n? Dann trefft meinen Schild und meine Klinge am Hafen und bringt die Lage wieder in Ordnung.", sourceObjective = "Trefft Habutu und Zolani am Kriegshafen der Rastari.", completion = "Das is' übler, als wir dacht'n.\n\nViel übler.", sourceObjectiveStatus = "unverified-source-field" }
quests[49123] = { id = 49123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todeskroggs", description = "Ihr habt Torga gehört. Wir müss'n die Bluttrolle angreif'n, wenn wir G'huuns Herold aufhalt'n woll'n.\n\nDie Bluttrolle ham riesige Kroggs in 'nem Lager in der Nähe. Wenn wir sie erledig'n, schwäch'n wir auch die Bluttrolle!\n\nDer Rest von uns geht voraus, um herauszufind'n, was diese Bluttrolle hier sonst noch vorham.", sourceObjective = "Tötet 12 Blutkroggs oder ihre Reiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[49124] = { id = 49124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tortollanerrettung", description = "Wenn Torga will, dass wir Euch helfen, G'huuns Herold zu töten, werden wir auch helfen. Aber als Erstes müssen wir unsere Leute retten.\n\nIch habe herausgefunden, dass die Bluttrolle unseren Freunden ganz in der Nähe das Blut entziehen und sie dann an die Kroggs verfüttern! \n\nSo darf kein Tortollaner sterben. Nicht nach hundert Jahren des Sammelns von Geschichten auf Azeroth.\n\nNehmt diese Schriftrolle. Sie beseitigt jede Form von Blutmagie, die die Trolle auf meine Freunde wirken.\n\nUnd passt gut darauf auf! Ich brauche sie unversehrt zurück!", sourceObjective = "Rettet 6 gefangene Tortollaner vor den Bluttrollen, indem Ihr Lashks Schriftrolle der Reinigung benutzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[49125] = { id = 49125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Negatives Blut", description = "Nun, Ihr wollt also den Herold eines Blutgottes töten? Dann müssen wir uns etwas überlegen.\n\nIn der Nähe gibt es verderbtes Blut, aus dem das Monster seine Macht speist. Ihr habt Glück, dass ich schon zuvor Geschichten über dieses Ding gehört habe.\n\nNehmt diese Schriftrolle, aber seid vorsichtig damit! Sie wird das verderbte Blut vernichten, von dem Jungo sich nährt.\n\nOh, und Ihr müsst die Schriftrolle finden, die Holbruck bei sich trug. Es ist die Schriftrolle der Hand des Schicksals. Sie ist SEHR machtvoll. Wir werden sie brauchen.", sourceObjective = "Zerstört 8 Einheiten verderbtes Loablut mit der Schriftrolle der Läuterung und beschafft die Schriftrolle der Hand des Schicksals.", progress = "Habt Ihr die Schriftrolle bekommen und Euch um das verderbte Blut gekümmert?", completion = "Gut! Wie es aussieht, konntet Ihr den Herold schwächen. Und Ihr habt die Schriftrolle! Seid vorsichtig, sie ist uralt! \n\nHolbruck sprach immer davon, wie machtvoll diese Schriftrolle ist. Wir werden sehen, ob er damit recht hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[49126] = { id = 49126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hand des Schicksals führen", description = "Ich habe gute und schlechte Nachrichten für Euch bezüglich der erforderlichen Vernichtung von G'huuns Herold. Zuerst die schlechten.\n\nZwischen uns und dem nächsten Gebiet steht eine ganze Armee von Skeletten. Ich vermute, dass sie mithilfe von Torgas Blut wiederbelebt wurden.\n\nDie gute Nachricht ist, dass Ihr mit Holbrucks Schriftrolle die mächtige Hand des Schicksals beschwören könnt.\n\n...Und wiederum eine schlechte Nachricht ist, dass die Schriftrolle bei Holbrucks Ableben beschädigt wurde und nur noch einmal verwendbar ist.\n\nAlso, nehmt diese Schriftrolle und vernichtet die Skelettarmee!", sourceObjective = "Verwendet die Schriftrolle der Hand des Schicksals, um die Hand des Schicksals zu beschwören und 50 Untote an der Blutküste zu vernichten.", completion = "Ich habe die Vernichtung von hier aus sehen können. Hm... Vielleicht sollte ich diese Schriftrolle für zukünftige Zwecke instand setzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49130] = { id = 49130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loa-freie Ernährung", description = "Prinzessin Talanji glaubt, dass wir fast bereit sind, G'huuns Herold zu töten. Vielleicht hat sie recht. Oder wir sind schon alle so gut wie tot. Wer weiß?\n\nAber was ich weiß, ist, dass die Bluttrolle hier... Fleisch von Torga abhacken und wegtragen. Bah!\n\nSoweit ich weiß, verwenden sie das Fleisch des armen Torga als Energie für ihre Blutrituale. Das muss aufhören!\n\nZieht los und nehmt den Bluttrollen die Fleischstücke ab. Ich werde mir überlegen, was damit anzustellen ist.", sourceObjective = "Besorgt 6 Stücke Fleisch von Torga von den Bluttrollen.", progress = "Habt Ihr... schon das Loa-Fleisch?", completion = "So darf man mit Torgas Überresten nicht umgehen, {name}. Ich werde dafür sorgen, dass sie ordnungsgemäß vernichtet werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[49131] = { id = 49131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Boden heiligen", description = "Wir sin' kurz davor, den Herold zu schwäch'n, {name}. Das is' unser letzter Vorstoß. Die ganze Gegend is' voll mit Blutmagie.\n\nWährend Ihr die ganze Zeit gekämpft habt, hab ich Totems gemacht, mit denen man die Gegend von der Blutmagie befrei'n kann.\n\nNehmt diese Totems und platziert sie in der Umgebung. Sie sollt'n dafür sorg'n, dass der Einfluss der Blutmagie in der Gegend geringer wird.\n\nDann dürfte der Herold so schwach sein, dass wir ihn am Ende tatsächlich töt'n können.", sourceObjective = "Platziert 4 Weihetotems in der Gegend.", completion = "Die Blutmagie in diesem Gebiet verflüchtigt sich. Es is' an der Zeit, loszuschlag'n, bevor die Bluttrolle noch mehr Vorteile erhalt'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[49132] = { id = 49132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schädel der Schädelberster zerbersten", description = "Es ist so, {name}, ich werde erst dann wieder glücklich sein, wenn wir diesen Herold getötet haben und alles wieder so ist wie vorher.\n\nBis dahin müsst Ihr Euch um diese monströsen Bluttrolle namens \"Schädelberster\" kümmern. Reizender Name, oder?\n\nSoweit ich weiß, stehen sie in Verbindung mit diesem Herold. Vielleicht sind sie deswegen so riesig.\n\nWenn Ihr die Schädelberster tötet, wird der Herold vielleicht noch weiter geschwächt. Oder er wird noch zorniger und tötet uns alle.\n\nWir werden sehen.", sourceObjective = "Tötet 4 Blutschädelberster.", completion = "Prinzessin Talanji sagte etwas darüber, dass sie fühlen würde, wie die Blutmagie aus Torga entweicht. Ich hoffe, sie hat recht damit.", sourceObjectiveStatus = "unverified-source-field" }
quests[49133] = { id = 49133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antorus, der Brennende Thron: Das Herz von Argus", description = "Hatuun hat mir erzählt, dass Sargeras nach dem Fall von Argus befahl, einen Tempel der Dunkelheit tief im Inneren des Planeten zu errichten. Wir wissen nur wenig darüber, denn nur die treuesten Akolythen des Titanen erhalten Siegel, die ihnen Eintritt gewähren.\n\nWenn wir diese Siegel beschaffen könnten, wäre es vielleicht möglich, sie in die Vindikaar zu integrieren. Dann könnten unsere Streitkräfte einen Angriff direkt auf das finstere Herz von Argus starten.", sourceObjective = "Besorgt 4 Siegel des Dunklen Titanen von Aggramar in Antorus, dem Brennenden Thron, auf dem Schwierigkeitsgrad 'Normal'.", progress = "Habt Ihr die Siegel gefunden?", completion = "Mit diesen Siegeln kann die Vindikaar die Verteidigung des Brennenden Throns umgehen.\n\nEs ist an der Zeit, unseren Vorteil zu nutzen und den Krieg zu beenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[49134] = { id = 49134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antorus, der Brennende Thron: Das Herz von Argus", description = "Hatuun hat mir erzählt, dass Sargeras nach dem Fall von Argus befahl, einen Tempel der Dunkelheit tief im Inneren des Planeten zu errichten. Wir wissen nur wenig darüber, denn nur die treuesten Akolythen des Titanen erhalten Siegel, die ihnen Eintritt gewähren.\n\nWenn wir diese Siegel beschaffen könnten, wäre es vielleicht möglich, sie in die Vindikaar zu integrieren. Dann könnten unsere Streitkräfte einen Angriff direkt auf das finstere Herz von Argus starten.", sourceObjective = "Besorgt 4 Siegel des Dunklen Titanen von Aggramar in Antorus, dem Brennenden Thron, auf dem Schwierigkeitsgrad 'Heroisch'.", progress = "Habt Ihr die Siegel gefunden?", completion = "Mit diesen Siegeln kann die Vindikaar die Verteidigung des Brennenden Throns umgehen.\n\nEs ist an der Zeit, unseren Vorteil zu nutzen und den Krieg zu beenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[49135] = { id = 49135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antorus, der Brennende Thron: Das Herz von Argus", description = "Hatuun hat mir erzählt, dass Sargeras nach dem Fall von Argus befahl, einen Tempel der Dunkelheit tief im Inneren des Planeten zu errichten. Wir wissen nur wenig darüber, denn nur die treuesten Akolythen des Titanen erhalten Siegel, die ihnen Eintritt gewähren.\n\nWenn wir diese Siegel beschaffen könnten, wäre es vielleicht möglich, sie in die Vindikaar zu integrieren. Dann könnten unsere Streitkräfte einen Angriff direkt auf das finstere Herz von Argus starten.", sourceObjective = "Besorgt 4 Siegel des Dunklen Titanen von Aggramar in Antorus, dem Brennenden Thron, auf dem Schwierigkeitsgrad 'Mythisch'.", progress = "Habt Ihr die Siegel gefunden?", completion = "Mit diesen Siegeln kann die Vindikaar die Verteidigung des Brennenden Throns umgehen.\n\nEs ist an der Zeit, unseren Vorteil zu nutzen und den Krieg zu beenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[49136] = { id = 49136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jungo, Herold von G'huun", description = "Jetzt gilt es, {name}. Die Blutmagie is' jetzt so geschwächt, dass wir dem Herold von G'huun tatsächlich Schaden zufüg'n können.\n\nWir müss'n alle zusammen kämpf'n, wenn wir das Ding aufhalten woll'n. Wir treff'n uns dann in Torga drinnen.\n\nWir dürf'n nich' verlier'n. Wenn die Bluttrolle Torgas Blut kontrollier'n, werd'n wir sie nich' mehr aufhalt'n können.", sourceObjective = "Besiegt Jungo, Herold von G'huun.", completion = "Wir haben's geschafft, {name}. Die Bluttrolle hab'n nich' mehr das Blut von Torga, um ihre Armee zu stärk'n.\n\nIch weiß, dass wir auf Torgas Hilfe gehofft hatt'n, aber wenigstens hab'n wir die Bluttrolle aufgehalt'n.\n\nWir müssen Rokhan und die andren find'n, und auch Krag'wa... wenn er noch lebt.\n\nHäh? Sieht aus, als ob Lashk etwas will...", sourceObjectiveStatus = "unverified-source-field" }
quests[49138] = { id = 49138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käpt'n Gulnakus Schatz", description = "<Die schlecht gezeichnete Karte ist mit Flecken übersät, aber auf ihr sind drei Stellen nahe dem Hafen von Zem'lan markiert, an denen der Skelettkapitän möglicherweise einen Schatz vergraben hat. Der Schatz könnte sich an jedem dieser drei Orte befinden.\n\nGanz unten auf der Karte steht ein Befehl gekritzelt: Legt Fallen!>", sourceObjective = "Sucht nach Käpt'n Gulnakus Schatztruhe.", progress = "<Sie ist fest verschlossen. Zum Öffnen benötigt Ihr den Schlüssel des Käpt'ns.>", completion = "<In der Truhe befindet sich ein funkelnder Schatz.>", sourceObjectiveStatus = "unverified-source-field" }
quests[49139] = { id = 49139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Arsenal einer Armee", description = "Meine Aufgabe ist es, die Ruine auszukundschaften, Gefahren zu erkennen und den besten Weg hinein zu finden.\n\nDer Großteil der wertvollen Waffen in dieser Ruine befindet sich in zwei Lagerhäusern.\n\nDie Lagerhäuser werden aber unglücklicherweise von Gespenstern bewacht. Mächtige Zandalarigeister, die an diesen Ort gebunden sind.\n\nIch... Wir brauchen diese Waffen. Schaltet die Gespenster aus, sodass ich... wir sicher hineingelangen können.", sourceObjective = "Tötet die Gespenster von Mugabu und Jam'jen, damit Umi die Lagerhäuser durchkämmen kann.", completion = "Wir sind ein gutes Team, {name}.\n\nNehmt diesen kleinen Bonus von mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[49141] = { id = 49141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomatie und Dominanz", sourceObjective = "Benutzt Vorriks Stab, um 6 Unterdrückungsspitzen der Treulosen Energie zu entziehen.", completion = "<Vorrik lächelt, als Ihr ihm den Stab zurückgebt.>\n\nIch danke Euch, {name}. Ich muss zugeben, ich habe angespannt Eure Rückkehr erwartet. Es ist schon viele Jahre her, seit der Stab das letzte Mal nicht an meiner Seite war.\n\nDoch ich tat gut daran, mein Vertrauen in Euch zu setzen. Man kann die Macht im Stab ja praktisch brummen hören.", sourceObjectiveStatus = "unverified-source-field" }
quests[49143] = { id = 49143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essenz der Lichtmutter", description = "Das ist der entscheidende Moment, {name}. Unsere Kampagne darf nicht ins Stocken geraten.\n\nXe'ra ist zwar gefallen, aber ich spüre immer noch ihre Präsenz überall um uns herum. Das Licht, das einst ihr Herz erhellte, kann unserer Sache immer noch Kraft spenden.\n\nZweifellos hat Xe'ras Verlust Turalyon tief getroffen. Ich werde alles in meiner Macht Stehende tun, um seinem aufgewühlten Geist Trost zu spenden, während Ihr die verbleibenden Überreste der Naaru sucht.", sourceObjective = "Sammelt 3 Lichtüberreste.", progress = "Obwohl Xe'ra nicht mehr ist, kann uns ihre Essenz immer noch bei unserem Kampf helfen.", completion = "Oh ja, ich spüre das Licht in diesen Fragmenten. Lasst Eure Hoffnung nicht fahren, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[49144] = { id = 49144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorn der Zandalari", description = "Mit'n Mogu kann man nich' red'n. Sie respektier'n nur eins: Stärke.\n\nDavon ham die Zandalari mehr als alle andren, aber unsre Reihen sin' ausgedünnt. Auf 'nen Kampf mit ihnen sin' wir einfach nich' vorbereitet.\n\nIhr habt Euch aufm Schlachtfeld als fähig erwies'n... soweit <ein/eine:r> {race} das überhaupt sein kann. Würdet Ihr uns als <\"Botschafter\"/\"Botschafterin\"> bei diesen Wüstlingen dien'? Zeigt denen, dass die Zandalari nich' allein dasteh'n!", sourceObjective = "Tötet 8 Marodeure oder Unterwerfer der Kao-Tien oder aufgeladene Wächter.", completion = "Ihr kämpft gut, aber unsre Arbeit is' längst noch nich' getan.", sourceObjectiveStatus = "unverified-source-field" }
quests[49145] = { id = 49145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Troll wird zurückgelassen", description = "Das is' der wichtigste Hafen der Zandalari. Zum Glück war'n die meisten von unsren Schiffen ausgelauf'n, als die Mogu kamen, aber der Kriegshafen is' immer noch 'ne intakte Festungsanlage für die Stadt.\n\nDiese Mogu sind nich' an 'ner verlass'nen Küste gelandet, {class}. Hier gibt's genug mutige Krieger, die um ihre Leb'n kämpf'n.\n\nNehmt diese Pfeife und versammelt die Krieger. Sie werd'n ihren Klang hör'n und wiss'n, dass sie nich' allein sind.", sourceObjective = "Ruft 12 Verteidiger der Rastari zusammen.", completion = "Unsre Krieger werd'n es Euch so bald nicht vergess'n, dass Ihr Euer eignes Leben riskiert habt, um sie zu rett'n. Vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[49146] = { id = 49146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geistiges Eigentum", description = "Ihr seid kein Zandalari, aber in Eurem Geist brennt 'n Feuer aus Leidenschaft, wie ich's lang nicht geseh'n hab.\n\nIch bin der Wellenbinder. Durch mich erhalt'n unsre Schiffe den Segen der Loa. Ich werd nicht zulass'n, dass diese sprechend'n Felsen mein Land besudeln.\n\nSammelt meine Schmuckstücke ein und holt meinen Zauberfolianten und 'n paar unsrer Gefall'nen, die ich für solche Anlässe aufgespart habe.\n\nDiese Monster denken wohl, die ham schon gewonnen, aber Bwonsamdi wird die bald in Empfang nehm'n.", sourceObjective = "Findet Kaza'jins zurückgeholten Schmuck, den Zauberfolianten der Anderen Seite und die verehrten Überreste.", progress = "Habt Ihr mein Zeug?", completion = "Das habt Ihr gut gemacht. Meine Freunde auf der Andren Seite sin' erfreut.\n\nJetzt kommen wir zum spaßig'n Teil.", sourceObjectiveStatus = "unverified-source-field" }
quests[49147] = { id = 49147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demonstration der Stärke", description = "Bald is' die Zeit ihres Anführers gekomm'. Zuerst müss'n wir aber seine Leutnants loswerd'n. Unser Vorteil is' dahin, wenn die sich neu formier'n.\n\nJao-Ti is' der Erste. Legenden besag'n, dass Lei Shen selbst ma' über ihn gesagt hat, dass er 'ne starke Verbindung zu den Stürmen hat. Er is' der Anführer von den Sturmbindern der Mogu.\n\nDer andre is' Unterwerfer Zheng. Ein Sklaventreiber, der sogar die von Kul Tiras in den Schatten stellt. Solche Verderbtheit habt Ihr noch nich' geseh'n.\n\nTötet die beide und lasst die leid'n. Die Mogu mög'n furchterregende Krieger sein, aber wir sin' noch furchterregender.", sourceObjective = "Tötet Jao-Ti den Donnernden und Unterwerfer Zheng.", completion = "Sie hab'n noch viel Schlimmeres verdient, da könnt Ihr Euch sicher sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[49148] = { id = 49148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles zerfällt", description = "Die Armee von den Mogu wird durch die Steinkrieger, die sie zum Leb'n erweck'n, von Minute zu Minute größer. Es wird nich' lange dauern, bis ihre Streitmacht wieder zu voller Stärke zurückgefund'n hat.\n\nVerflucht sei Zul! Es is' ihm verbot'n gewes'n, seine Haustiere hierherzubring'n... un' auch, den Donnerkönig in Pandaria wiederzuerweck'n.\n\nWir sin' die letzte Verteidigungslinie zwischen der Armee von den Mogu und der Stadt. Wir müss'n einschreit'n, solang's noch möglich is'!", sourceObjective = "Zerstört 8 sturmgebundene Eroberer.", completion = "Sie werd'n sich erhol'n, wenn wir uns nicht beeil'n. Das is' vielleicht unsre einzige Chance.", sourceObjectiveStatus = "unverified-source-field" }
quests[49149] = { id = 49149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heißt das Voodoo willkommen", description = "Diese Ungläubigen denk'n wohl, wir sin' schwach und am Boden zerstört.\n\nZandalari sterb'n aber niemals wirklich.\n\nIch hab den Totenschädel, den Habutu Euch gegeb'n hat, mit 'nem bisschen Voodoo belegt, sodass er auf die Andre Seite durchbrech'n kann. Ihr müsst meine Geisterobelisken nutz'n, um seine Macht zu bündeln. Danach könn' die übernehm'n.", sourceObjective = "Benutzt die Schädelpfeife der Rastari und aktiviert 5 Geisterobelisken.", progress = "Dieses Land wird uns niemals irgendwer wegnehm'n!", completion = "Fühlt Ihr's? Die Geister fließ'n durch Euch... und sie sin' erfreut.", sourceObjectiveStatus = "unverified-source-field" }
quests[49160] = { id = 49160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torgas ewige Rückkehr", description = "Nun, wir haben es geschafft. Trotzdem macht das unseren Plan nicht weniger verrückt. Eine Sache muss aber noch erledigt werden.\n\nIch habe Torga viele Jahre lang besucht. Er hat mir Geschichten von mächtigen Schriftrollen erzählt. Dabei hat er eine erwähnt, mit der man den Geist eines Loas befrieden kann.\n\nIch denke, Ihr solltet sie lesen. Also, falls Ihr KLUG genug seid, sie lesen zu können.\n\nAch! Nehmt einfach die Schriftrolle und lest sie, bevor mir noch Zweifel kommen.", sourceObjective = "Verwendet LashksSchriftrolle der ewigen Rückkehr, um Torgas Geist Frieden zu schenken.", progress = "Ihr könnt doch die Schriftrolle lesen, oder?", completion = "Sieht aus, als würde uns das noch eine ganze Weile beschäftigen. Lashk und ich müssen uns um eine Menge Dinge kümmern, wenn wir helfen wollen.\n\nIch weiß sogar, wo Ihr Euren Trollfreund findet... und Krag'wa.", sourceObjectiveStatus = "unverified-source-field" }
quests[49178] = { id = 49178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meine liebsten Dinge", description = "Die Welt da draußen ist hart.\n\nEs gibt Piraten, tödliche Monster.\n\nKohldampfsören hat endlosen Ärger mit seiner Verdauung.\n\nNichts hilft einem besser, Ruhe zu bewahren, als ein altes Andenken. Etwas, das einen an seine Heimat denken lässt. Etwas, für das man immer weitermacht.\n\nHört Euch ein wenig im Lager um. Findet heraus, was die Leute dort draußen im Priel verloren haben. Wenn Ihr davon etwas zurückbringen könntet, wäre das eine großzügige Geste.\n\nIch? Oh... Ich habe ein Medaillon verloren...\n\nIst egal. Das ist zu klein, das würdet Ihr nie finden. Ist nichts Besonderes. Macht Euch keine Gedanken darüber.", sourceObjective = "Fragt den leutseligen Piet, Kohldampfsören und Friemelkalle über ihre verlorenen Andenken aus und findet sie danach im Klagenden Priel.", progress = "Wir alle haben etwas in den Fluten verloren.\n\nManche mehr als andere.", completion = "Ich hätte nie geglaubt, dass Ihr wirklich all diese Sachen finden würdet!\n\nWir haben nicht viel, aber nehmt wenigstens dies für Eure Bemühungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49181] = { id = 49181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glänzendes Medaillon", description = "<Zwischen dem mit den Wellen auf und ab tanzenden Treibgut fällt Euch ein metallenes Glänzen ins Auge. Ihr wühlt im dichten Seetang und entdeckt ein einfaches, aber stabiles Medaillon.\n\nAls Ihr es öffnet, entdeckt Ihr die Zeichnung einer Frau mit feuerroten Haaren.\n\nIhr Arm ruht auf der Schulter einer Frau mit kurzem rotbraunem Haar und die beiden lächeln den Künstler warmherzig an.>", sourceObjective = "Bringt das glänzende Medaillon Jette der Klinge zurück.", progress = "Hm? Was habt Ihr denn da?", completion = "Ist das etwa?\n\n<Jette nimmt das Medaillon und öffnet es vorsichtig. Tränen sammeln sich in ihren Augen, als sie es wieder schließt und in ihrer Jacke verstaut.>\n\nIch danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[49185] = { id = 49185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Wiedersehen", description = "Schön zu seh'n, dass Ihr unversehrt seid, {name}. Nazmir ist ein Ort voller Alpträume, aber Ihr haltet Euch wirklich wacker.\n\nRokhan und ich ham Eure Horde davon überzeugt, dass wir mehr Unterstützung brauch'n. Er bereitet sich darauf vor, sich mit der Verstärkung zu treff'n.\n\nWir brauch'n immer noch die Hilfe der Loa. Wie sieht es mit Bwonsamdi und Hir'eek aus?", sourceObjective = "Erzählt Talanji von Eurer Erfahrung mit Bwonsamdi und Hir'eek.", completion = "Kann sein, dass wir doch noch Glück hab'n. Vielleicht bekomm'n wir Torgas Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
