quests[49200] = { id = 49200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und noch mehr intakte Dämonenaugen" }
quests[49218] = { id = 49218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schiffbrüchigen", description = "Wie ich sehe, haben die Sirenen noch jemanden erwischt. Habt Ihr ein Glück, dass sie Euch noch nicht die Haut abgezogen haben.\n\nWenn Ihr Vorräte aufstocken oder Euch am Feuer wärmen wollt, begebt Euch einfach zum Lager auf dem Hügel hinter mir.\n\nAlle dort wurden hier angespült, genau wie Ihr. Inzwischen müssen sich Besatzungen von vier oder fünf Schiffswracks angesammelt haben. Sie halten zusammen und versuchen zu überleben.\n\nSprecht mit Jette der Klinge. Denkt nicht zu viel über ihren Namen nach, sie ist eigentlich ganz lieb.", sourceObjective = "Sprecht mit Jette der Klinge an der Schiffbruchhöhe.", completion = "Ah, Ihr müsst vom letzten Schiffswrack stammen. Diese verdammten Sirenen werden jeden Tag dreister.", sourceObjectiveStatus = "unverified-source-field" }
quests[49223] = { id = 49223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein großes Ding will Weile haben", description = "Hallo noch mal! Ich habe gute Neuigkeiten.\n\nUnser gemeinsamer Bekannter Karl-Jan, der uns in Freihafen zum Narren gehalten hat, hat endlich sein Versteck verlassen.\n\nIch habe mit ihm über Briefe kommuniziert, die mithilfe unzähliger Mittelsmänner überbracht wurden, und sogar einige kleine Vollmachtsgeschäfte abgeschlossen, um sein Vertrauen zu gewinnen. In unserer letzten Korrespondenz war er damit einverstanden, mich persönlich zu treffen und ein Geschäft abzuwickeln.\n\nEr glaubt, er trifft eine gnomische Frisörin namens Pixy Spindelfunken mit einem Faible für pochierte Pelze.\n\nStattdessen wird er aber auf Euch treffen.", sourceObjective = "Tötet Karl-Jan.", completion = "Langsam und stetig, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[49224] = { id = 49224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Netherlichttiegel", description = "Der Tiegel surrt voller Macht. Schon bald werden Eure Waffen strahlen wie die Sterne!\n\nFür eine Chance, die Legion hier zu vernichten, werden wir diese Stärke brauchen.\n\n{name}, Ihr habt große Strapazen auf Euch genommen, um uns zu diesem Punkt zu führen. Die Ehre, die Macht des Tiegels erstmals zu verwenden, muss die Eure sein.", sourceObjective = "Erfüllt ein Relikt mit Netherlichtstärkung, indem Ihr den Netherlichttiegel verwendet.", completion = "Wenn Eure Waffe an Stärke gewinnt, können wir sie sogar mit noch mehr Macht erfüllen, aber ihre jetzige Stärke sollte für den Moment mehr als ausreichend sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[49225] = { id = 49225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Anführerin hinterher", description = "Die Einwohner und die Liga arbeiten gemeinsam daran, die Relikte aus der Höhle auf dem Hügel zu bergen. Doch es scheint, als hätten wir die letzten Bewohner der Höhle verärgert. Ich glaube, die Marinesoldaten können die Expedition vorerst beschützen, doch ich weiß nicht, wie lange noch.\n\nWir brauchen Eure Hilfe, bevor alles den Bach runtergeht! Findet Hilde Feuerbruch, die Anführerin unserer Expedition. Sie ist aus irgendeinem Grund in die Höhle zurückgekehrt.", sourceObjective = "Findet Hilde Feuerbruch.", completion = "Ihr seid gekommen, um zu helfen? Na endlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[49226] = { id = 49226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstummen der Schwestern", description = "Die Sirenen des Priels haben schon endlose Schiffe in ihr Verderben gelockt. Es wäre ein Segen für alle Seefahrer, wenn jemand sie beseitigen würde.\n\nAber Ihr könnt sie nicht einfach alle töten. Nur ein Narr würde so etwas probieren.\n\nDie echte Gefahr sind die Ältesten. Man nennt sie die \"Schwestern\". Sie sind größer, klüger und stärker als die Jüngeren. Ihre Stimmen dringen bis aufs Meer hinaus und locken die großen \"Fänge\" an.\n\nIch konnte zwei von ihnen bis zu einem Versteck am nördlichen Ende des Priels verfolgen, kann sie aber nicht allein stellen.", sourceObjective = "Tötet Patheope und Nolpe.", completion = "Indem Ihr ihr tödliches Lied verstummen lassen habt, habt Ihr zahllose Leben gerettet.", sourceObjectiveStatus = "unverified-source-field" }
quests[49227] = { id = 49227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Generalschlüssel", description = "Keiner der Schlüssel, die Ihr gefunden habt, hat gepasst! Wir brauchen einen anderen Plan...\n\nIch habe gehört, dass Aufseherin Meerensen einen Generalschlüssel hat, mit dem man alle Schlösser im Areal öffnen kann. Es ist gefährlich, aber Ihr müsst diesen Schlüssel für mich besorgen!\n\nSie leitet die Bergbauarbeiten aus dem Innern der Höhle heraus. Sobald Ihr den Schlüssel habt, müsst Ihr alle gefangenen Vulpera, die Ihr finden könnt, befreien.\n\nWenn Ihr meine Freunde gerettet habt, kommt zu mir zurück und befreit mich. Viel Glück!", sourceObjective = "Holt Meerensens Generalschlüssel und befreit damit 8 gefangene Vulpera.", progress = "Ihr haltet Euch an Euren Teil der Abmachung und ich mich an den meinen.", completion = "Natürlich freue ich mich, Euch wiederzusehen, {name}. Zuverlässige Retter sind heutzutage schwer zu finden.\n\nIch bezahle Euch wie vereinbart, aber ich werde nicht allzu lange hierbleiben!", sourceObjectiveStatus = "unverified-source-field" }
quests[49229] = { id = 49229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf der Ruinen", description = "Irgendwas hat in der Höhle eine Falle ausgelöst und plötzlich erwachten die ganzen Ruinen zum Leben. Ich vermute mal, dass unsere Burschen dort drinnen nicht wirklich in der Lage sind, zu kämpfen.\n\nKönntet Ihr ein paar der lebenden Ruinen ausschalten, um ihnen zur Flucht zu verhelfen?", sourceObjective = "Tötet 6 uralte Beschützer.", completion = "Gegen Geister hab ich ja schon gekämpft, aber gegen Ruinen selbst noch nie.", sourceObjectiveStatus = "unverified-source-field" }
quests[49230] = { id = 49230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lokale Spezialitäten", description = "Ich bin am VERHUNGERN.\n\nNicht so am Verhungern, wie als wir hier angekommen sind, aber Ihr wisst schon... emotional am Verhungern.\n\nIn letzter Zeit hatte ich bei Austern nicht viel Glück und Seetangsuppe schlägt mir auf den Magen. Wenn ich noch mehr von dem Zeug essen muss, werden die anderen Schiffbrüchigen mich vermutlich den Haien zum Fraß vorwerfen.\n\nWie die Gezeitenlauerer wohl schmecken? Die sehen schön saftig aus. Könnte man sicher schmackhaft dämpfen.\n\nWürdet Ihr mir ein paar bringen? Ich bin kein großer Jäger. Aber ich würde sie mit Euch teilen!", sourceObjective = "Sammelt 5 saftige Lauererschwänze.", progress = "<Sörens Magen knurrt laut.>", completion = "Oh, Ihr habt mir das Leben gerettet!\n\nWartet nur einen Augenblick, die habe ich im Nu gekocht!", sourceObjectiveStatus = "unverified-source-field" }
quests[49232] = { id = 49232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retten, was zu retten ist", description = "Birch und ich helfen der Expedition mit den Feldstudien. Ich bin kein großer Kämpfer, aber wenn ich noch einen Fehler mache, dann werden sie mich degradieren!\n\nWürdet Ihr mir helfen, ein paar der Relikte zu besorgen, die sich in der Höhle in Kisten befinden?", sourceObjective = "Sammelt 6 Drustrelikte.", progress = "Habt Ihr genug Relikte entdeckt?", completion = "Ich kann es kaum erwarten, herauszufinden, was für Macht ich daraus gewinnen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[49233] = { id = 49233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich bin Druide, kein Priester", description = "Auch die Überreste vorheriger Eindringlinge sind beim Aktivieren der Hauptfalle wiederauferstanden.\n\nKrummelunte verlangt meine Unterstützung. Auch wenn ich nur wenig vom Bannen der Untoten verstehe, habe ich vermutlich eine Lösung entdeckt.\n\nIch habe meinen Stab angepasst, damit er ihren Fluch aufhebt. Nehmt ihn und findet heraus, ob Ihr ihnen damit helfen könnt.", sourceObjective = "Befreit 5 verfluchte Räuber.", completion = "Ein weiterer Sieg für die Magie der Druiden! Dieser Stab ist viel wirkungsvoller als Krummeluntes Gerätschaften.", sourceObjectiveStatus = "unverified-source-field" }
quests[49234] = { id = 49234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marinesoldat an Land", description = "Ein riesiges Exemplar dieser Steinkreaturen hat ziemlich viele Marinesoldaten getötet, als wir versuchten, die Höhle zu evakuieren. Sie hat uns bisher nicht verfolgt, aber sie einfach nur zu ignorieren, ist viel zu riskant.\n\nSie muss vernichtet werden!", sourceObjective = "Tötet den erwachten Wächter.", completion = "Ich habe von hier aus das Echo der fallenden Steine in der Höhle gehört. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[49239] = { id = 49239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleider machen Leute", description = "Einst war Freihafen für jedermann offen, doch nun haben die Eisenfluträuber sich selbst zu den Besitzern erklärt. Sie machen den Ort dicht und schicken alle fort, die nicht zu ihrer Mannschaft gehören.\n\nGlücklicherweise suchen sie auch neue Leute.\n\nZieht das an. Denkt nicht darüber nach, woher wir es haben.\n\nWir geben uns als neue Rekruten aus, sammeln im Inneren Informationen und kehren rechtzeitig zum Abendessen nach Boralus zurück! Carsten mag einem mit seiner Art zwar häufiger Salz in die Wunde streuen, aber meine Suppe hat er noch nie versalzen.", sourceObjective = "Setzt den Hut der Eisenfluträuber auf und betretet mit Finn zusammen Freihafen.", completion = "Keine Sorge, Venrik ist ein guter Kerl. Dem vertraue ich voll und ganz.", sourceObjectiveStatus = "unverified-source-field" }
quests[49242] = { id = 49242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stachel um Stachel", description = "Oh, hallo. Tut mir leid, wir bekommen hier nicht viele Leute vom Festland zu sehen.\n\nDieses Grundstück war die Farm meines Mannes Sam. Er hat sich jeden Tag um die Zwiebelfelder gekümmert, bevor der Fluch über Schluchtbach kam und ihn mitriss.\n\nOhne meinen Mann bleibt mir nur noch dieser Bauernhof und selbst den verliere ich bald an diese Stachelratten.\n\nIch bitte Fremde nur ungern um Hilfe, aber könntet Ihr diese Pest ausrotten?", sourceObjective = "Tötet 6 territoriale Stachelratten auf Hagendorns Feldern.", completion = "Ich danke Euch, {class}.\n\nVielleicht kann ich diesem verfluchten Land durch die Wiederbelebung der Felder ein wenig von Sams Güte zurückgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[49259] = { id = 49259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und Gerechtigkeit für alle", description = "Danke, dass Ihr mir geholfen habt, mein Ansehen bei meinen Leuten wiederherzustellen, {class}. Ich stehe in Eurer Schuld und werde meinem Vater sicher davon berichten.\n\nIn der Zwischenzeit sollten wir herausfinden, was dieser Herzbannzirkel ist und was er in unserem Land will. Ich hoffe, der Marschall kann uns dabei weiterhelfen.\n\nAber das Wichtigste zuerst. Könntet Ihr vielleicht diese Seile lösen? Sie fangen an, meine Haut aufzuscheuern.", sourceObjective = "Verlasst die Galgenschäre mit Luzilla Kronsteig.", progress = "Wollen wir?", completion = "Die Lage ist viel bedrohlicher, als ich angenommen hatte. Der Zirkel hat das Haus Kronsteig übernommen?! Das darf nicht sein!\n\nAber... Sagtet Ihr nicht, dass sie ihre Kraft aus einer uralten Ruine beziehen?\n\nIch glaube, ich habe da eine Idee.", sourceObjectiveStatus = "unverified-source-field" }
quests[49260] = { id = 49260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe beim Packen", description = "Ich bin hergekommen, um so viele Relikte wie möglich zu holen. Reinkommen war kein Problem, aber ich mache mir Sorgen, dass man mich beim Einpacken erwischt.\n\nWürdet Ihr ein wenig Wache stehen, während ich die Relikte sicher in meiner Tasche verpacke?", sourceObjective = "Beschützt Archäologin Feuerbruch.", completion = "Alles, was unserer Aufmerksamkeit würdig ist, sollte in meiner Tasche sein. Vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[49261] = { id = 49261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krabbeneintopf für die Mannschaft", description = "Solltet Ihr nicht in den Minen sein? Also, wenn Ihr Meerensen nichts sagt, sage ich auch nichts. Ich würde auch nicht gerne in den Minen festsitzen. \n\nWir könnten hier sogar etwas Hilfe brauchen. Die Mannschaft wird allmählich mürrisch. Wir essen seit Wochen nur irgendeine Pampe und dann und wann mal eine Ratte. \n\nWie ich höre, kann einer unserer Deckmatrosen einen hervorragenden Krabbeneintopf kochen. Kann ich auf Euch zählen, um das Fleisch zu beschaffen?", sourceObjective = "Sammelt klumpiges Krabbenfleisch von Sandkrabblern.", progress = "Das wird schön, zur Abwechslung mal etwas anderes als Ratten zu essen.", completion = "Das habt Ihr gut gemacht, {name}. Heute Abend werden wir wie Könige speisen!", sourceObjectiveStatus = "unverified-source-field" }
quests[49262] = { id = 49262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bandenjagd", description = "Es ist schwierig, ein Schiff so fern der Heimat ordentlich zu führen. Die Mannschaft wird unruhig, wenn sie zu lange an Land festsitzt.\n\nIch habe von Deckmatrosen gehört, die herumschleichen und Vorräte stehlen. Wenn die Mannschaft glaubt, unter meiner Aufsicht unseren Arbeitgeber bestehlen zu können, kann sie sich auf was gefasst machen!\n\nIch brauche jemanden, der diesem zwielichtigen Treiben ein Ende setzt und der Mannschaft eine Nachricht sendet.\n\nDiebstahl wird nicht toleriert!", sourceObjective = "Stellt 8 zwielichtige Deckmatrosen.", completion = "Gut, dass ich mich auf Euch verlassen kann, dass hier nichts außer Kontrolle gerät.", sourceObjectiveStatus = "unverified-source-field" }
quests[49266] = { id = 49266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Äonenschmiede", description = "Die Lichtgeschmiedeten waren lange ein Leuchtfeuer der Hoffnung im Kampf gegen die Legion.\n\nAllerdings wissen nur wenige, was es bedeutet, den Zorn des Lichts zu verkörpern.\n\nDiese wenigen Champions der Armee des Lichts sind bereit, ihre entscheidende Prüfung anzutreten.\n\nErweist Ihr uns die Ehre, dem Ereignis beizuwohnen?", sourceObjective = "Werdet <Zeuge/Zeugin> des Rituals der Lichtgeschmiedeten.", progress = "Es gibt mir Hoffnung, dass wir solche Verbündeten gefunden haben.", completion = "T'paartos ist... voller Eifer. Er hat ein gutes Herz und in ihm brennt ein Feuer, das selbst unter den Lichtgeschmiedeten nur wenige besitzen. Vielen Dank, dass Ihr für seine Sicherheit gesorgt habt, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[49268] = { id = 49268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haialarm", description = "Vor Kurzem ist ein großer Schwarm Haie in die flacheren Gewässer des Hafens gezogen. Ich hatte schon mal mit kleineren Erkrankungen zu tun. Sie wurden durch fremdartige Schadstoffe verursacht, die Tiere an die Küste eingeschleppt hatten.\n\nVielleicht haben sich die Haie in den tieferen Gewässern etwas eingefangen, das sie jetzt hier einschleppen? Tötet einige Haie, die zu nah ans Pier gezogen sind. Ich muss die Gezeiten auf Veränderungen überprüfen.", sourceObjective = "Tötet 6 angriffslustige Schreckensrachen.", completion = "Leider... hat sich an den Gezeiten nichts verändert.", sourceObjectiveStatus = "unverified-source-field" }
quests[49274] = { id = 49274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgrums Untersuchung", description = "Heda. Wo Ihr Euch die Hände ohnehin schon schmutzig gemacht habt, können wir doch auch einen Handel machen, oder?\n\nIch will nicht um den heißen Brei herumreden. Es gibt hier ein Relikt, den Odem von Xibala. Ich weiß nicht, wer Xibala ist oder wieso die Allianz diesen Atem will, aber ich bekomme ein hübsches Sümmchen Gold, wenn wir den besorgen können.\n\nDas heißt, für Euch ist auch was drin, wenn Ihr wisst, was ich meine.\n\nIch habe mit meiner Ausrüstung mit Messungen begonnen, aber noch keine Ergebnisse. Geht hinaus in die Ruinen und gebt den Kästchen, die Ihr dort seht, einen kleinen Tritt, damit das schneller geht.", sourceObjective = "Überprüft Ausgräber Morgrum Glutsteins Erkundungsausrüstung in den Ruinen von Xibala.", completion = "Stellt mir keine Fragen, auf die Ihr keine Antworten wollt, {name}.\n\nAber Ihr habt gute Arbeit geleistet und jetzt hab ich, was brauche, um den Atem aufzuspüren.", sourceObjectiveStatus = "unverified-source-field" }
quests[49276] = { id = 49276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spannende Erkundung", description = "Ich bin Acadia, Acadia Tistelstein!\n\nIch vertrete hier vor Ort die Interessen der Forscherliga. Wenn es irgendwo Dreck umzuschichten gibt, sind wir nur allzu gern bereit, die Grabungen zu übernehmen!\n\n<Acadias Lächeln verblasst.>\n\nDiese Dunkeleisenzwerge sind mir allerdings etwas zu eifrig darauf bedacht, immer tiefer und schneller zu graben. Da Ihr ein starkes, fähiges Mitglied der Allianz seid, glaubt Ihr, Ihr könntet, äh... mit gutem Beispiel vorangehen?\n\nNur zu, hier ist ein frisches Fossil, das etwas Aufmerksamkeit vertragen könnte.", sourceObjective = "Helft Acadia Tistelstein dabei, ein Fossil von Xibala auszugraben.", progress = "Acadia hat mir gesagt, Ihr habt jetzt das Sagen. Das werden wir noch sehen.", completion = "Wir wissen beide, dass Ihr eigentlich nicht so viel Dreck unter Euren Fingernägeln haben wolltet.\n\nKeine Ursache.", sourceObjectiveStatus = "unverified-source-field" }
quests[49278] = { id = 49278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirituelle Wiederherstellung", description = "Das hier war 'n Bwonsamdi geweihter Ort, aber jetz' is' es nur noch 'ne Ruine. Selbst die Geister konnt'n der Vergänglichkeit nich' entkomm' und ham nur ihre ausgelaugten Hüllen zurückgelass'n.\n\nWir werd'n sie wieder aufersteh'n lass'n.\n\nHier, ich hab ihre Seelen in diesem Glücksbringer gesammelt. Wendet ihn auf die ausgelaugten Geister an, damit wir den Ort wieder zu dem mach'n, was er ma' war.", sourceObjective = "Verwendet Hanzabus Glücksbringer, um die Geister von Zo'bal auferstehen zu lassen.", completion = "Die Geister wach'n wieder über Zo'bal!\n\nUn' jetzt zu unsrer Abmachung...", sourceObjectiveStatus = "unverified-source-field" }
quests[49282] = { id = 49282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgrums ausgedehnte Untersuchung", description = "Ich habe mir die Messwerte meiner kleinen Kästchen angesehen und ich glaube, ich weiß, wo wir als Nächstes suchen müssen. Die Asche von Xibala gehört quasi mir.\n\nWir sollten uns mitten in den Ruinen treffen, unter diesem großen, grinsenden Schädel am Berghang, um meine Untersuchung fortzusetzen.\n\nDiese Apparate abzulesen ist Schwerstarbeit und ich glaube nicht, dass wir da oben allein sein werden.\n\nMeint Ihr, Ihr könnt mir Rückendeckung geben?", sourceObjective = "Helft Ausgräber Morgrum Glutstein bei einer Untersuchung.", completion = "Diese nichtsnutzige, miese, Asche klauende...!!\n\nWir nehmen die Verfolgung auf, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[49283] = { id = 49283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer sucht die Sucher?", description = "Zandalar steckt voller uralter Geheimnisse, das kann ich Euch sagen. Es ist so faszinierend.\n\nWir hörten Geschichten von einer Region im Südosten, in der Schiffe vom Kurs abgekommen sein sollen. Einige verschwanden sogar!\n\nRaku ist vor einiger Zeit zusammen mit einer Gruppe besonders wissbegieriger Sucher aufgebrochen, um dort in der Nähe eine Bucht zu erforschen. Schiffswracks und Mysterien, wer könnte da widerstehen?\n\nAber wir hätten schon längst von ihm hören müssen. Wir Tortollaner mögen nicht die Schnellsten sein, aber wir sind zuverlässig.\n\nWürdet Ihr bitte nachsehen, ob es ihnen gut geht?", sourceObjective = "Findet die Sucher an der Küste im Südosten und sprecht mit Batu.", completion = "Wir sind dankbar für seine Fürsorge und dafür, dass Ihr gekommen seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[49284] = { id = 49284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frohe Kunde", description = "Ihr kommt zur rechten Zeit, {class}.\n\nUnsere Gruppe wollte sich planmäßig hier treffen, und das schon vor zwei Tagen. Es ist noch niemand zurückgekehrt. \n\nIch möchte nicht voreilig sein und es zu früh in die Stadt melden. Aber weder kann ich hier weg noch kann ich den kleinen Koba alleinlassen. \n\nNehmt diese Schriftrolle. Seht zu, wen oder was ihr aufspüren könnt. Bringt so viele wie möglich mit zurück.", sourceObjective = "Benutzt die abgestimmte Schriftrolle der Verschollenen und spürt die verschwundenen Erkunder auf.", completion = "Seid gegrüßt, Nachbar! Es muss für Batu völlig rätselhaft gewesen sein, dass wir nicht zurückgekehrt sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[49285] = { id = 49285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winzige Schätze", description = "Die Erwachsenen sind unterwegs auf einer Forschungsmission. Also bin ich hiergeblieben und habe geduldig gewartet, so wie sie es mir gesagt haben.\n\nDann sind diese Monster gekommen und haben meine besten Schätze gestohlen! Und sie haben meine Schnecke Schnuckie mitgenommen, meinen besten Freund auf der ganzen Welt!\n\nSie haben alles mitgenommen. Dann sind sie weggelaufen, und ich bin nicht so schnell...\n\nKönnt Ihr sie bitte zurückholen und meine Familie finden?", sourceObjective = "Sammelt alle Schätze von Koba.", progress = "Mein Junges... Wenn sie Hand an es gelegt haben...", completion = "Kobas Lieblingssachen! Ich hoffe, dass er an Ort und Stelle geblieben ist. Er ist immer so ungeduldig.\n\nHabt Dank, {race}. Bald werden ich und mein Junge wieder vereint sein.\n\nUnd Schnuckie hat darum gebeten, dass Ihr das kleine Schneckchen auf all Euren zukünftigen Abenteuern mitnehmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[49286] = { id = 49286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weisheit hinter Schloss und Riegel", description = "Oh, hallo, <mein Freund/meine Liebe>. \n\nHier scheint mehr vor sich zu gehen, als wir erwartet hatten...\n\nWir suchten. Wir fanden. Wir studierten... und dann wurden wir gefangen genommen. Es gibt hier Naga. Damit hatten wir nicht gerechnet.\n\nIn dieser Höhle gibt es einen ganz üblen Burschen. Wenn Ihr ihm den Schlüssel abnehmen könntet, wäre uns das eine große Hilfe.\n\nKeine Sorge, wir werden hier warten.", sourceObjective = "Nehmt Sli'thrus den Schlüssel ab.", progress = "Haben wir zu viel verlangt?", completion = "Wir setzen uns besser in Bewegung. Ich glaube nicht, dass wir diesmal einfach abwarten können, bis die Naga weiterziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49287] = { id = 49287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschollene Schildkröten", description = "Gezeitenherrin Nazesh kanalisiert Ihre Magie auf einen Felsen, den sie in einem der Becken oben gefunden haben. Sie versucht es schon seit Tagen, und sie beginnen zu verzweifeln.\n\nDer Rest meiner Gruppe wurde gefangen genommen und in Käfige gesperrt. Sie wollen Geheimnisse von uns erfahren, die wir nicht kennen.\n\nWenn ihnen klar wird, dass sie aus uns Tortollanern nichts herausbekommen, fürchte ich, dass die Naga etwas Furchtbares tun werden.\n\nBefreit die Sucher. Wir werden die Pläne der Naga gemeinsam durchkreuzen.", sourceObjective = "Rettet die Tortollaner, die von den Nazeshi gefangen genommen wurden.", completion = "Solange meine Freunde in Sicherheit sind, kann ich hier in Ruhe weitermachen. Vielen Dank, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[49288] = { id = 49288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Papierjäger", description = "Bei unserer Gefangennahme haben sie uns alles abgenommen, was wir hatten... also auch unsere wundervollen Schriftrollen!\n\nDie Hexen der Naga erschaffen Stürme. Sie versuchen geheim zu halten, was sie hier tun, aber sie wollen Macht für ihre Königin. \n\nWir durchschauen ihren Wahnsinn... Sie verfolgen ganz bestimmte Ziele.\n\nHolt unsere Werke von den Sturmbeschwörern der Nazeshi zurück, bevor sie sie für ihre schändlichen Ziele einsetzen können.", sourceObjective = "Beschafft 5 Schriftrollen der Erkunder.", progress = "Ich sollte mir wirklich mal ein paar mehr Schriftrollenbehälter anschaffen...", completion = "Anscheinend ist alles hier. Und das mit nur wenigen Beschädigungen. Sehr beeindruckend!\n\nWas haben wir hier? Mal sehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[49289] = { id = 49289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein besonderer Stein", description = "Gezeitenherrin Nazesh ist gleich da drüben auf dem Hügel, {name}.\n\nDa ist irgendetwas. Irgendetwas, das Azshara unbedingt haben will.\n\nDie Naga dürfen keinen Erfolg haben. Wenn Ihr ein kleines Stück von diesem Stein beschaffen könnt, bringt es uns bitte.\n\nNehmt diese Schriftrolle. Sie wird Euch im Kampf helfen.\n\nEs wird Zeit, dass wir ihre Truppen ein für alle Mal in die Wellen zurückstoßen.", sourceObjective = "Besiegt Gezeitenherrin Nazesh und bringt den Grund für die Anwesenheit der Naga in Erfahrung.", progress = "Was habt Ihr herausgefunden?", completion = "Gut gekämpft, Abenteurer. Fürwahr, gut gekämpft! \n\nWas das auch für ein Stein ist, hinter dem die Naga her waren, heute haben sie ihn nicht bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49290] = { id = 49290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Perfektion gereift", description = "Grüße, <junger Freund/junge Freundin>. Ich bin Roko. Ich handle mit Spezialitäten und exotischen Waren.\n\n<Roko holt ein kleines Holzfass unter seinem Panzer hervor.>\n\nDieser Bourbon ist einhundert Jahre alt. Das weiß ich, weil ich ihn vor einhundert Jahren gekauft habe.\n\nEin Mann in Freihafen bietet im Tausch dafür eine seltene Schriftrolle, doch leider lassen sie mich dort nicht hinein. Wie mir scheint, ist der Hafen keineswegs mehr \"frei\".\n\nWenn sie Euch hineinlassen, könntet Ihr ja vielleicht den Tauschhandel für mich übernehmen? Dafür wäre ich Euch etwas schuldig.", sourceObjective = "Liefert den hundertjährigen Bourbon an Karl-Jan in Freihafen.", progress = "Gehört Ihr zu den Eisenfluträubern?\n\nIch habe Eure Leute schon bezahlt! Lasst mich in Ruhe!", completion = "Oh! Der Bourbon von diesem Schildkrötenkerl!\n\nAlso... kommt er wohl nicht selbst? Und ich schätze, Ihr seid nicht den Eisenfluträubern ergeben.\n\nNun gut, gebt schon her.", sourceObjectiveStatus = "unverified-source-field" }
quests[49292] = { id = 49292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Algencocktail", description = "Jetzt, da mein Tonikum endlich fertig ist, ist es äußert wichtig, dass wir es umgehend an alle Kranken verteilen.\n\nBitte nehmt diesen Krug und verteilt das Heilmittel unter den Kranken. Ich werde versuchen, den Rest zu beruhigen.", sourceObjective = "Verteilt das reinigende Tonikum an 6 kranke Bewohner der Angelpunktwerft.", completion = "In meinem ganzen Leben habe ich nie solch eine Krankheit gesehen. Wir müssen ihren Ursprung finden!", sourceObjectiveStatus = "unverified-source-field" }
quests[49293] = { id = 49293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasionsoffensive", description = "Wir dürfen der Legion keine einzige Welt überlassen. Führt unsere Invasionspunktoffensive fort und zermalmt die verdammte Legion.", sourceObjective = "Schließt 3 normale Invasionspunkte ab.", progress = "Die Offensive geht weiter.", completion = "Die Niederlage der Legion steht kurz bevor.", sourceObjectiveStatus = "unverified-source-field" }
quests[49295] = { id = 49295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kanten schneiden", description = "Wir haben den Hügel halten können, aber diese Weidenkreaturen haben uns jetzt umzingelt.\n\nWir werden nicht in die Stadt eindringen können, wenn es uns nicht gelingt, sie von unseren Flanken zu vertreiben. Das ist also Eure Aufgabe, {class}.\n\nVersucht, ein paar von ihnen im Waldgelände zu erledigen, dann müssen wir uns nur noch um eine Front kümmern.", sourceObjective = "Tötet 8 fluchgeformte Familiare am Abgeholzten Ufer.", completion = "Ausgezeichnet. \n\nIch habe mich auf diesem Hügel schon etwas beengt gefühlt.", sourceObjectiveStatus = "unverified-source-field" }
quests[49299] = { id = 49299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Innerer Feind", description = "Ich will nichts schönreden, das ist hier wie im Irrenhaus.\n\nDie Regierenden sind gefallen. Sie haben ihre eigenen Seelen und ebenso die Seelen ihrer Arbeiter an irgendwelche dunkleren Mächte verkauft.\n\nIch werde nicht nachgeben.\n\nAufseher Behrens hat in seiner Gier nach Macht die ganze Wache geopfert. Zeigt ihm, was für ein Narr er ist.", sourceObjective = "Tötet Aufseher Behrens.", completion = "Für mehr Macht gab Behrens alles, was er hatte. Eine Schande, dass es so kommen musste.", sourceObjectiveStatus = "unverified-source-field" }
quests[49300] = { id = 49300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Wildnis" }
quests[49302] = { id = 49302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der tödlichste Fang", description = "He! Wir dürfen keine Zeit verlieren!\n\nOffenbar hat Tiefenwacht noch ein Ass im Ärmel... und das ist der Fang des Tages!\n\nDas wird eine Jagd, an die man sich erinnern wird, und ich werde sie mir nicht entgehen lassen.\n\nOkri wird Euch raus zur Mauer fliegen. Macht Euch bereit!", sourceObjective = "Begleitet Okri zum Meerestor und tötet Viq'Goth.", progress = "Noch nie habe ich ein Monster mit solch düsterer Energie erblickt. Wir dürfen es nicht durchlassen!", completion = "Meine ungenügende Herrschaft führte dazu, dass Tiefenwacht nicht nur unsere Fischerei übernahm, sondern fast das ganze Dorf.\n\nIch kann nicht mehr untätig danebenstehen und solchen Leuten erlauben, mich aus dem Weg zu schubsen und zu tun, wie sie belieben! Das habe ich nun begriffen und das dank Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[49309] = { id = 49309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturz des Donners", description = "Kriegsherr Kao befehligt die Mogu von diesem Kriegsschiff. Wird Zeit, seine Belagerung zu beend'n.\n\nIch kann die Verstärkung, die Kao zu Hilfe komm' könnte, wohl eine Weile aufhalten, aber nich' ewig.\n\nSeid vorsichtig. Kao war einer der best'n Generäle des Donnerkönigs. Er wird nich' kampflos aufgeb'n.", sourceObjective = "Tötet Kriegsherr Kao.", progress = "Ohne Kao als Anführer sin' die Mogu leichte Beute.", completion = "Der König is' in Gefahr!", sourceObjectiveStatus = "unverified-source-field" }
quests[49310] = { id = 49310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prophetenplan", description = "König Rastakhans Leben is' in großer Gefahr. Zul is' weitaus mächtiger, als es scheint.\n\nUns bleibt nich' viel Zeit. Ihr müsst den König warnen, bevor Zul handeln kann.\n\nZolani kann Euch dorthinbring'n. Geht jetzt!", sourceObjective = "Reist auf Narbenschnabel nach Dazar'alor.", completion = "Wir wurd'n verrat'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[49314] = { id = 49314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd auf Zardrax", description = "{name}, Ihr könntet mir bei 'ner Sache helf'n.\n\nTalanji sagte, dass Schattenjäger Da'jul und sein Anhänger Kal'dran losgezog'n sin', um einen Lich namens Zardrax zu jag'n.\n\nSie sin' unterwegs zum Grabhügel. Ich fürchte, sie ham sich damit übernommen.\n\nKönnt Ihr nach ihnen schau'n und ihnen vielleicht helf'n? Wir dürf'n keine weit'ren Verbündeten hier verlier'n.", sourceObjective = "Findet Schattenjäger Da'jul am Grabhügel.", completion = "Wurd... auch... Zeit... dass... jemand... auftaucht! Haltet uns... diesen Lich... vom Hals!", sourceObjectiveStatus = "unverified-source-field" }
quests[49315] = { id = 49315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schreckensperlenabsprache" }
quests[49327] = { id = 49327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drängt sie zurück!", description = "Die Treulosen belagern unser Zuhause. \n\nDas ist nicht das erste Mal, dass sie uns angreifen, und sicher auch nicht das letzte Mal. Aber wir müssen den Tempel beschützen!\n\nTut, was in Eurer Macht liegt, um ihre Belagerung aufzubrechen und sie zurückzuschlagen.", sourceObjective = "Haltet den Angriff der Treulosen auf das Sanktum der Ergebenen auf.", completion = "Die Treulosen werden ihre Belagerung niemals aufgeben, aber Eure Bemühungen haben uns etwas Zeit verschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[49333] = { id = 49333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufbau eines Arsenals", description = "In unserem Kampf gegen die Treulosen stehen wir auf verlorenem Posten. Wir sind zahlen- und waffenmäßig unterlegen. \n\nUnsere wenigen Waffen reichen nicht aus, um damit den gesamten Tempel auszurüsten. \n\nMit ein paar mehr Speeren und Dolchen hätten wir aber zumindest eine Chance, ihnen standzuhalten, bis unser Loa wieder bei uns ist.", sourceObjective = "Sammelt 20 Sethrakwaffen innerhalb des Tempelübergriffs.", progress = "Wir brauchen Waffen, {name}.", completion = "Ihr habt genug gebracht, um jeden, der willig und fähig ist zu kämpfen, eine Waffe in die Hand zu geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[49334] = { id = 49334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein mächtiger Gefangener", description = "Anscheinend haben die Treulosen unsere Verteidigung durchbrochen, während ich fort war.\n\nSie müssen hinter Vorriks Schlüssel her sein. Nur aus dem Grund würden sie ihn lebend gefangen nehmen.\n\nBitte, {name}. Ihr müsst für die sichere Rückkehr unseres Anführers sorgen.", sourceObjective = "Findet Vorrik und befreit ihn aus seiner Gefangenschaft.", completion = "Ich schulde Euch mein Leben, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[49335] = { id = 49335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Himmelsrufergemetzel", description = "Einige unter den Treulosen verfügen über die Fähigkeit, den Sturm zu beherrschen. Sie nennen sich selbst \"Himmelsrufer\" und nutzen ihre Magie, um große Säulen zu beschwören, die Erde in Sand verwandeln.\n\nNur die Himmelsrufer können diese Säulen erschaffen. Wenn Ihr sie ausschaltet, schaltet Ihr auch die Fähigkeit der Sethrak aus, ihre Kriegslager zu erweitern.", sourceObjective = "Tötet 6 Himmelsrufer der Sethrak im Tempelübergriff.", completion = "Ohne ihre Himmelsrufer wird der Übergriff der Treulosen ins Wanken geraten.", sourceObjectiveStatus = "unverified-source-field" }
quests[49340] = { id = 49340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlüssel der Hüter", description = "Serrik sagte, dass Ihr vielleicht in Zul'Ahjin etwas Bedeutendes entdeckt habt?\n\nIch fürchte, wir haben nicht viel Zeit.\n\nWas also habt Ihr gefunden?", sourceObjective = "Sprecht mit Vorrik und erschließt die Bedeutung von Sulthis' Stein.", completion = "Dank Euch haben wir jetzt zwei der Schlüssel. Korthek hat immer noch den dritten.\n\nWenn wir diesen Schlüssel bekommen könnten, wäre Mythrax für immer in seinem Grab gefangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[49345] = { id = 49345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergrabener Schatz" }
quests[49348] = { id = 49348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der entweihte Tempel", description = "Die Geister der Gläubigen ström'n in meinen Tempel. Ihr seht sie doch da draußen, oder? \n\nSie komm', um die Andre Seite zu betret'n un' sich meinem Reich anzuschließ'n. Aber es dring'n auch Geister in die Tempelanlage ein, die Bwonsamdi den Rücken gekehrt ham. Sie huldig'n \"G'huun\" und verbreit'n ihre Blutmagie über die Nekropole.\n\nDas muss jetz' aufhör'n!\n\nGeht da raus und entfernt diese Entweihung, die meinen Tempel beschmutzt.", sourceObjective = "Vernichtet 5 schändliche Entweihungen in der Nekropole.", completion = "Das habt Ihr gut gemacht, Mann. Ich fühl mich in der Nekropole schon wieder fast wie zu Haus.", sourceObjectiveStatus = "unverified-source-field" }
quests[49354] = { id = 49354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erinnerung an den Sonnenbrunnen", description = "Der Lordregent beabsichtigt, der Ersten Arkanistin Thalyssra unseren Sonnenbrunnen zu zeigen.\n\nIch weiß nicht, ob er Alleria Windläufer gestatten wird, am Treffen teilzunehmen, aber wir sind dazu eingeladen.", sourceObjective = "Schließt das Szenario \"Erinnerung an den Sonnenbrunnen\" ab.", completion = "Das kam nicht unbedingt unerwartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[49366] = { id = 49366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für den Verwundeten", description = "<Dieser Zandalari scheint mehr tot als lebendig.\n\nNeben ihm liegt ein zerbrochener Pfeil auf dem Boden. Es sieht so aus, als ob er diese Flasche fallen gelassen hat, bevor er zusammengebrochen ist.\n\nIhr nehmt das Fläschchen an Euch. Ist das vielleicht ein Gegengift?>", sourceObjective = "Behandelt den verwundeten Zandalari.", completion = "Danke, Fremder. Knapper geht's wohl nich'.", sourceObjectiveStatus = "unverified-source-field" }
quests[49370] = { id = 49370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung des Chronisten", description = "'n Stück weiter wartet Chronist Jabari in 'nem Käfig auf seine Opferung.\n\nEiner nach dem andern wurde abgeholt. Ich hab ihre Schreie gehört. Mit dem Blut ham sie die Blutmagie genährt und den Rest ham sie verfüttert.\n\nJabari ist jetzt der Letzte. Ich bin zu schwach, um ihn zu rett'n.\n\nHolt ihn da raus, damit wir zu Prinzessin Talanji zurückkehr'n können.", sourceObjective = "Befreit Chronist Jabari.", completion = "Also, das war mal grau'nhaft. Nur noch 'n paar Teile un' wir könn'n uns hier vom Acker mach'n. Für immer.", sourceObjectiveStatus = "unverified-source-field" }
quests[49376] = { id = 49376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Süßes Ding", description = "Gerade rechtzeitig! Ich dacht schon, mit mir wär's vorbei.\n\nIch bin dran schuld, dass wir hier angehalt'n ham. Unser Team wollte zurück.\n\nDiese Kroggs sin' das Problem. Sie werd'n blutig gebor'n und durch grausame Ausbildung zu Monstern gemacht. Sie lass'n sich leicht beeinfluss'n und folgen einem, wenn man sie anlockt.\n\nErregt die Aufmerksamkeit von einem der kleinen Ekelbatz'n in der Nähe. Ich will herausfind'n, ob meine Theorie korrekt is'.", sourceObjective = "Fangt einen Kroggling ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[49377] = { id = 49377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runter mit ihrem Kopf", description = "Kriegsmatrone Nagla führt ihre Truppen mit 'ner Brutalität und Stärke, die wir nich' erwartet ham. \n\nDie Bluttrolle entweih'n alles, was sie berühr'n, un' woll'n alles vernicht'n, was übrig bleibt. \n\nWie heißt es so schön? \"Kein Kopf, keine Probleme!\" \n\nIch will ihren Kopf hier als Trophäe seh'n, als Beweis dafür, dass unsre Brüder gerächt wurd'n.", sourceObjective = "Bringt den Kopf von Kriegsmatrone Nagla als Trophäe zurück.", progress = "Lebt sie noch?", completion = "<Satao spuckt auf den Boden.>\n\nOhne dieses Monster is' die Welt 'n besserer Ort.", sourceObjectiveStatus = "unverified-source-field" }
quests[49378] = { id = 49378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vertrauen verdienen", description = "Wenn man den Jungtieren Vertrauen beibring'n kann, gibt's noch Hoffnung für diese Art.\n\nDie stammen zwar von 'ner bösen Blutlinie ab, aber macht die das direkt zu Monstern? Wenn Ihr seine Selbstsicherheit aufbau'n könnt, könnte er 'n wertvoller Verbündeter werd'n.\n\nEr braucht nur 'n bisschen Zuneigung und 'n Haufen Ess'n! Die Bluttrolle findet er bestimmt lecker.", sourceObjective = "Füttert den Kroggling.", completion = "Er ist jetzt gesättigt! Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[49379] = { id = 49379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kroggs unerwünscht", description = "Bei den ausgebildet'n Kroggs gibt's keine Chance mehr, sie zu ändern.\n\nWir müss'n sie töt'n, sonst werd'n die Jungen niemals 'ne Chance ham.", sourceObjective = "Tötet 5 Schlachtkroggs.", completion = "Wenigstens is' ihr Leiden vorüber.", sourceObjectiveStatus = "unverified-source-field" }
quests[49380] = { id = 49380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finsteres Juju", description = "He, hör mir ma' zu. Wir könn' mein' Kumpel ohne das Zeug, das uns in diesen Schlamassel gebracht hat, hier nich' rausschaff'n.\n\nWir ham drei Kugeln in dem Lager geseh'n. Sie enthalt'n die Macht der Blutmagie un' werd'n in schändlichen Ritualen verwendet.\n\nSie entzieh'n \"Freiwilligen\" die Energie, um Krag'was Kaulquappen zu verderb'n.\n\nWenn dieses Schicksal auch den Kindern des Loas droht, müsst Ihr die Sache beend'n.\n\nNehmt diese Phiole un' entleert die Blutkugeln. Der Chronist wird das untersuch'n müss'n.", sourceObjective = "Entleert die Blutkugeln.", completion = "Puh! Selbst ich kann die Verderbnis spür'n. Bestimmt kann Jabari die Geheimnisse lüft'n, die sich hier drinn'n verberg'n.\n\nIch danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[49382] = { id = 49382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neuer Freund", description = "Dieses Jungtier hat sich mit Euch angefreundet.\n\nBringt es zu Krag'wa.\n\nVielleicht hat er 'ne Möglichkeit, die Verderbnis zu heilen.", sourceObjective = "Sucht Krag'wa auf.", completion = "Dieses Jungchen gehört nich' mehr zu ihnen, aber zu uns wird er auch nie gehör'n. Passt auf ihn auf!\n\nIch danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[49393] = { id = 49393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Raubeine", description = "NEUE ARBEITSANGEBOTE!\n\nLiebt Ihr die Gefahr? Horden wilder Tiere? Gefährliche Abenteuer?\nSeid Ihr lieber draußen in der Wildnis als Euch hinter einem bequemen Stadtleben zu verstecken?\n\nNun, vielleicht könntet Ihr dann zu den RAUBEINEN passen, den Lieferanten aller Reitgreifen in Kul Tiras.\n\nMeldet Euch am Lager der Raubeine im Westwindwald, um mehr über dieses spannende Angebot zu erfahren.\n\nBewerber dürfen KEINE Angst vor Höhen, Federn und/oder dem Tod haben.", sourceObjective = "Sprecht mit Tagart beim Lager der Raubeine.", completion = "Ihr seid wegen des Angebots hier? Dann macht Euch auf was gefasst. Das wird kein Zuckerschlecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[49394] = { id = 49394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stillhalten", description = "Ihr wollt also ein Raubein werden? Dann müsst Ihr zuerst ein paar Prüfungen meistern. Das musste hier jeder, also meckert nicht herum.\n\nNehmt diese Scheren und bringt mir ein paar Ziegenfelle. Die Felle müssen von lebendigen Ziegen geschoren werden. So sind die Regeln. Und seid auf der Hut, diese Biester treten aus wie wild.", sourceObjective = "Verwendet die Ziegenschere bei 6 sanftmütigen Ziegen.", progress = "Habt Ihr die Felle?", completion = "Ihr habt es tatsächlich geschafft! Wie hat es den Ziegen gefallen? Habt Ihr die Hörner zu spüren bekommen? Hahaha!", sourceObjectiveStatus = "unverified-source-field" }
quests[49395] = { id = 49395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Bären und Bienen", description = "Hey, wenn Ihr sowieso dort unterwegs seid, könnt Ihr mir und den Jungs vielleicht ein wenig Honig besorgen?\n\nIm Wald gibt es überall Bienenstöcke, aber passt auf Eure Schreibtischfingerchen auf, denn die Bären hier werden ganz schön rabiat, wenn sie Honig wittern.", sourceObjective = "Tötet 8 Zottelpelze und sammelt 6 Stücke klebrigen Bienenhonig von Bienenstöcken in der Nähe.", progress = "Probleme mit Bären?", completion = "Ihr habt ja mehr auf Eurer Kleidung, als in den Flaschen. Ich würde Euch ja raten, Euch zu waschen, aber von uns hat das auch seit Wochen keiner mehr gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[49397] = { id = 49397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Um die Wurst" }
quests[49398] = { id = 49398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoch die Tassen!", description = "Schön Euch kennenzulernen. Mein Name ist Venrik. Ich lebe seit Jahren hier in Freihafen und kratze mir meinen Lebensunterhalt zusammen.\n\nFinn war früher eigentlich auch ein... naja, lassen wir das. Jeder Mann hat seine eigenen Leichen im Keller.\n\nIch kann Euch beiden wohl helfen, aber zuerst bekommt Ihr ein zünftiges Begrüßungsgeschenk aus Freihafen: ein ordentliches Getränk!", sourceObjective = "Bestellt Euch bei Venrik ein Getränk und trinkt es.", completion = "Es geht doch nichts über ein Getränk mit alten Freunden... und neuen!", sourceObjectiveStatus = "unverified-source-field" }
quests[49399] = { id = 49399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das große Ding", description = "Die Eisenfluträuber sammeln also die verschiedenen Mannschaften der Gesetzlosen um sich, um mit den Waffen von Aschenwind & Co. ein großes Ding zu drehen.\n\nIch habe so ein Gefühl, dass es dabei nicht um einen Angelausflug geht.\n\nWir sollten nachsehen, ob die kleineren Mannschaften Befehlspapiere bei sich haben. Schafft Ihr das?\n\nIch muss mich bedeckt halten und mich mit Venrik treffen. Wenn mich hier jemand erkennt, gibt es garantiert kein freundlich gemeintes Begrüßungsgetränk.", sourceObjective = "Beschafft die Befehle der Bilgeratten, die Befehle der Schwertwasserkorsaren und die Befehle der Schwarzzahnvandalen.", progress = "Habt Ihr was gefunden?", completion = "Ich... Ich werde versuchen, das hier zu verstehen.\n\nIhr müsst Finn helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[49400] = { id = 49400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekrutierung? Nein Danke!", description = "Harlan der Schmierige, der Kapitän der Eisenfluträuber, bildet sich in seinem Spatzenhirn wohl ein, dass Freihafen jetzt ihm gehört.\n\nEr zwingt die kleineren Mannschaften, sich ihm anzuschließen und pflastert die ganze Stadt mit diesen verdammten Rekrutierungsplakaten.\n\nTut mir einen Gefallen und reißt diese Plakate herunter, wenn Ihr welche seht. Lasst Euch dabei aber nicht erwischen, sonst dürft Ihr über die Planke gehen.", sourceObjective = "Reißt 6 Rekrutierungsplakate der Eisenfluträuber herunter.", completion = "Hah! Das wird sie hart treffen oder zumindest ärgern!", sourceObjectiveStatus = "unverified-source-field" }
quests[49401] = { id = 49401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rodrigos Horst", description = "Wir sollten uns zuerst mit Carsten und Taelia besprechen, bevor wir weitermachen.\n\n<Finn notiert etwas auf ein Stück Pergament und steckt es in eine kleine Kuriertasche.>\n\nDas sind alle Beweise, die wir bis jetzt haben, die die Handelskompanie Aschenwind mit den Waffen und den Piraten hier in Freihafen in Verbindung bringen.\n\nGebt sie Rodrigo. Er ist hinter dieser Taverne auf dem Dach. Er züchtet Papageien, die sich wunderbar als Flugboten eignen. Manche sind sogar so groß, dass man darauf reiten kann!\n\nRodrigo ist zwar nicht die allerhellste Leuchte an Deck, aber man kann ihm vertrauen!", sourceObjective = "Sprecht mit Rodrigo in Freihafen.", completion = "Okay, jetzt, da der Boss Bescheid weiß: zurück an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[49402] = { id = 49402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einer flog über das Aranest", description = "Ja, natürlich könnt Ihr auf den Hübschen fliegen. Das sind ganz liebe Tiere, sie helfen gerne!\n\nSeid Ihr auch hilfsbereit? Könnt Ihr mir vielleicht helfen?\n\nDiese lauten Männer kamen hierher und haben mich bedroht. Mich beeindruckt so etwas nicht, aber meine Hübschen sind vor Angst davongeflogen.\n\nWenn Ihr einige meiner Hübschen da draußen seht, bitte füttert sie hiermit!\n\nDas ist meine Spezialmischung. Das überzeugt sie sicher, wieder zurückzukommen.", sourceObjective = "Füttert 6 entflohene Aras.", progress = "Habt Ihr hier draußen Papageien gesehen? Oh, die armen Tiere frieren hier draußen bestimmt ganz schlimm.", completion = "Ihr habt es geschafft! Meine Hübschen sind wieder da!", sourceObjectiveStatus = "unverified-source-field" }
quests[49403] = { id = 49403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rodrigos Rache", description = "Die lauten Männer sind gemein, aber Ihr scheint nett zu sein!\n\nWollt Ihr Euch ein bisschen amüsieren?\n\nDie Hübschen lieben meine Spezialkekse, aber sie stopfen ihre Bäuche, und dann müssen sie... Ihr wisst schon.\n\nSpielen wir den fiesen Männern einen Streich! Fliegt auf den Hübschen und lasst sie ihr Geschäft verrichten.", sourceObjective = "Entfesselt ein 'Übles Bombardement' auf 100 Piraten in Freihafen.", completion = "Das wird ihnen eine Lektion sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[49404] = { id = 49404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alte \"Freunde\"", description = "Jemand muss Finn erkannt und verraten haben! Die Eisenfluträuber haben ihn zu einer \"Privataudienz\" bei Kapitän Harlan dem Schmierigen in den Ring der Beute gezerrt.\n\nFinn redet nicht gerne darüber, aber er war einst selbst Kapitän einer Mannschaft und Harlan war sein Erster Maat.\n\nDie beiden hatten nach einem missglückten Beutezug Streit und Finn gab daraufhin das Freibeuterleben auf. Ist eines Tages einfach verschwunden.\n\nHarlan nahm sich dann die fiesesten Mitglieder der Mannschaft und gründete die Eisenfluträuber.\n\nMit anderen Worten: Die Sache ist persönlich.", sourceObjective = "Rettet Finn aus dem Ring der Beute.", completion = "Es tut mir so leid, {name}. Ich bin so schnell gekommen, wie ich konnte!", sourceObjectiveStatus = "unverified-source-field" }
quests[49405] = { id = 49405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidiger von Daelins Tor", description = "Daelins Tor schützt den südlichen Kanal seit Jahrzehnten. Wenn es fällt, kann die Piratenflotte ungehindert zum Tiragardesund segeln!\n\nDie Seeleute an der Wachkuppe können jegliche Hilfe gut brauchen. Lasst uns aufbrechen!", sourceObjective = "Reist mit Taelia zur Wachkuppe.", completion = "Ihr seid gekommen, um zu helfen? Oh, den Gezeiten sei Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[49406] = { id = 49406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlachtfest in Zalamar" }
